// `import * as` returns a frozen Module Namespace — clone into a plain object
// so we can re-attach the addons under the same `THREE.X` names the legacy
// 16k-line body uses.
const THREE = Object.assign({}, THREE_NS);

// Keep modern color management enabled. The procedural PBR pass now uses sRGB
// color textures, ACES tone mapping, and physically plausible metalness, so
// retaining r170's color pipeline avoids the neon/washed-out legacy look.
THREE_NS.ColorManagement.enabled = true;
THREE.ColorManagement = THREE_NS.ColorManagement;

THREE.GLTFLoader      = GLTFLoader;
THREE.KTX2Loader      = KTX2Loader;
THREE.DRACOLoader     = DRACOLoader;
THREE.MeshoptDecoder  = MeshoptDecoder;
THREE.CCDIKSolver     = CCDIKSolver;
THREE.SkeletonUtils   = SkeletonUtils;
THREE.EffectComposer  = EffectComposer;
THREE.RenderPass      = RenderPass;
THREE.UnrealBloomPass = UnrealBloomPass;
THREE.ShaderPass      = ShaderPass;
THREE.GTAOPass        = GTAOPass;
THREE.SMAAPass        = SMAAPass;
THREE.OutputPass      = OutputPass;
THREE.MaathEasing     = MaathEasing;
THREE.MeshBVHRuntime  = {
  acceleratedRaycast: bvhAcceleratedRaycast,
  computeBoundsTree: bvhComputeBoundsTree,
  disposeBoundsTree: bvhDisposeBoundsTree
};
window.THREE = THREE;

const ANIMATION_MIDDLEWARE_RUNTIME = Object.freeze({
  version: ANIMATION_PIPELINE_VERSION,
  threeAddons: {
    GLTFLoader: !!GLTFLoader,
    KTX2Loader: !!KTX2Loader,
    DRACOLoader: !!DRACOLoader,
    MeshoptDecoder: !!MeshoptDecoder,
    SkeletonUtils: !!SkeletonUtils,
    CCDIKSolver: !!CCDIKSolver
  },
  libraries: {
    maath: !!MaathEasing,
    threeMeshBvh: !!(bvhAcceleratedRaycast && bvhComputeBoundsTree && bvhDisposeBoundsTree)
  },
  tooling: TOOLING_CAPABILITIES
});

// ─── Light-intensity bridge (r155+ physically-correct mode) ────────────────
// The old π boost made every authored source feel like a blown-out work light
// once the project moved to PBR. A smaller bridge keeps legacy levels readable
// while preserving warmer falloff, shadow depth, and material detail.
const _LIGHT_BOOST = 1.82;
for (const cls of ['AmbientLight','HemisphereLight','DirectionalLight','PointLight','SpotLight','RectAreaLight']) {
  const Orig = THREE_NS[cls];
  if (!Orig) continue;
  const Patched = function (...args) {
    const inst = new Orig(...args);
    inst.intensity *= _LIGHT_BOOST;
    // Lights must reach the viewmodel render layers too (world 0, vm 1/2, body 3).
    if (inst.layers) inst.layers.mask |= 0b1111;
    return inst;
  };
  Patched.prototype = Orig.prototype;
  Object.setPrototypeOf(Patched, Orig);
  THREE[cls] = Patched;
}

const STABLE_RENDERING_MODE=true;
function _forceStableVisualSettings(s){
  Object.assign(s,{
    rendererMode:'webgl',
    postEnabled:false,
    aoQuality:'off',
    bloomQuality:'off',
    colorGrade:false,
    filmGrain:false,
    chromaticAberration:false,
    sharpen:false,
    smaa:false,
    vignette:false,
    phase2SSR:false,
    phase2LUT:false,
    phase2DoF:false,
    phase2Volumetrics:false,
    phase2PlanarReflections:false,
    phase2Adaptive:false,
    phase2Sharpen:0,
    phase2TAA:false,
    ssrIntensityMul:0,
    scopePipEnabled:false,
    scopePipResolution:0,
    pixelRatioCap:1.0,
    renderScale:'auto'
  });
  return s;
}
function _readBootSettings(){
  try{
    const raw=localStorage.getItem('clearance_settings');
    const parsed=raw?JSON.parse(raw):{};
    return STABLE_RENDERING_MODE?_forceStableVisualSettings(parsed):parsed;
  }catch(_){
    return STABLE_RENDERING_MODE?_forceStableVisualSettings({}):{};
  }
}
const _BOOT_SETTINGS=_readBootSettings();
// Points at saved boot JSON until SETTINGS IIFE completes (avoids TDZ on SETTINGS during early _configureRenderStack).
let _SETTINGS_FOR_RENDER=_BOOT_SETTINGS;
const _AA_PBR_BOOT=_BOOT_SETTINGS.cheapMaterials!==true&&_BOOT_SETTINGS.pbrMaterials!==false;
function _legacyMaterialParamsToPbr(params={},kind='phong'){
  const shininess=Number.isFinite(params.shininess)?params.shininess:(kind==='lambert'?8:45);
  const spec=params.specular==null?0x202020:params.specular;
  const specC=new THREE_NS.Color(spec);
  const specLum=(specC.r+specC.g+specC.b)/3;
  const out={
    color:params.color==null?0xffffff:params.color,
    map:params.map||null,
    emissive:params.emissive==null?0x000000:params.emissive,
    emissiveMap:params.emissiveMap||null,
    emissiveIntensity:params.emissiveIntensity==null?1:params.emissiveIntensity,
    transparent:!!params.transparent,
    opacity:params.opacity==null?1:params.opacity,
    side:params.side==null?THREE_NS.FrontSide:params.side,
    alphaTest:params.alphaTest||0,
    roughness:THREE_NS.MathUtils.clamp(1-(shininess/320),0.18,kind==='lambert'?0.92:0.86),
    metalness:THREE_NS.MathUtils.clamp(specLum*.18,0,0.24),
    normalMap:params.normalMap||null,
    roughnessMap:params.roughnessMap||null,
    metalnessMap:params.metalnessMap||null,
  };
  if(params.fog!==undefined)out.fog=params.fog;
  if(params.depthWrite!==undefined)out.depthWrite=params.depthWrite;
  if(params.depthTest!==undefined)out.depthTest=params.depthTest;
  if(params.blending!==undefined)out.blending=params.blending;
  return out;
}
if(_AA_PBR_BOOT){
  const OrigPhong=THREE_NS.MeshPhongMaterial;
  const OrigLambert=THREE_NS.MeshLambertMaterial;
  const PatchedPhong=function(params={}){
    const mat=new THREE_NS.MeshStandardMaterial(_legacyMaterialParamsToPbr(params,'phong'));
    mat.userData.aaSourceMaterial='MeshPhongMaterial';
    mat.shininess=params.shininess==null?45:params.shininess;
    mat.specular=new THREE_NS.Color(params.specular==null?0x202020:params.specular);
    return mat;
  };
  PatchedPhong.prototype=THREE_NS.MeshStandardMaterial.prototype;Object.setPrototypeOf(PatchedPhong,OrigPhong);
  const PatchedLambert=function(params={}){
    const mat=new THREE_NS.MeshStandardMaterial(_legacyMaterialParamsToPbr(params,'lambert'));
    mat.userData.aaSourceMaterial='MeshLambertMaterial';
    mat.shininess=8;mat.specular=new THREE_NS.Color(0x080808);
    return mat;
  };
  PatchedLambert.prototype=THREE_NS.MeshStandardMaterial.prototype;Object.setPrototypeOf(PatchedLambert,OrigLambert);
  THREE.MeshPhongMaterial=PatchedPhong;
  THREE.MeshLambertMaterial=PatchedLambert;
}

// ─── Original game body begins here (legacy r128 inline script) ────────────
// ─── EXTERNAL ASSETS — disabled, full procedural fallback ───────────────────
// Soldier.glb / deagle.glb integration is disabled. Both procedural meshes
// (the multi-box enemy body in the Enemy class, and the 35-piece DE_MESHES
// pistol) render correctly in r170 with the light/color fixes above and have
// no skinning/inverseBindMatrix gotchas. Variable names (SOLDIER_GLTF, MESHY_*,
// DEAGLE_GLB) are kept as `null` so the downstream code paths that gate on
// them — applyMeshyRig, attachMeshyAnims, attachDeagleGlbModel — turn into
// no-ops and the procedural rendering takes over automatically.
const SOLDIER_GLTF=null;
const MESHY_CHAR=null;
const MESHY_ANIMS=null;
const DEAGLE_GLB=null;
function _meshyToast(msg,color){
  const d=document.createElement('div');
  d.style.cssText='position:fixed;top:8px;left:50%;transform:translateX(-50%);background:'+(color||'#222')+';color:#fff;padding:6px 14px;font:12px monospace;border-radius:4px;z-index:99999;pointer-events:none;opacity:.92';
  d.textContent=msg; document.body.appendChild(d);
  setTimeout(()=>{d.style.transition='opacity .6s';d.style.opacity='0';setTimeout(()=>d.remove(),700);},5000);
}
// ─── desert_eagle.glb load DISABLED ────────────────────────────────────────
// Reverting to the procedural box-art Deagle (DE_MESHES — slim HK USP-T blockout, same
// build style as the M4: deBody, deSlide, deSer1..2, deBarrel, deHammer,
// deTrig, deGrip, deMag, etc.). The GLB asset never felt at-home with the
// rest of the procedural geometry, and the bundled "Take 001" animation
// timing didn't match the FPS cadence. Keeping the file at
