  7:{RW:28,RD:64,RH:4.00,layers:['lower','deck']},           // Azure Yacht — narrow
  8:{RW:44,RD:56,RH:4.50,layers:['raisedFloor','floor']},    // Server Farm Δ — grid
  // ── ACT III — "The Apparatus" expansion (B09-B12) ─────────────────────
