  10:{RW:36,RD:66,RH:5.00,layers:['nave','transept','choirloft']}, // Cathedral of San Marco — sanctified vault
  11:{RW:30,RD:68,RH:4.00,layers:['lower','deck','bridgeWing']},   // Karelia Freighter — open-ocean steel maze
