// ── Server farm rack wall panel — for B8 walls
const _serverWallTex=(()=>{
  const c=document.createElement('canvas');c.width=512;c.height=512;
  const g=c.getContext('2d');
  g.fillStyle='#06080e';g.fillRect(0,0,512,512);
  // Rack rows (horizontal bands of LEDs)
  for(let y=8;y<512;y+=32){
    g.fillStyle='#10141a';g.fillRect(0,y,512,28);
    // LED rows
    for(let i=0;i<60;i++){
      const x=8+i*8;
      const r=Math.random();
      const col=r<.6?'#40c8ff':(r<.85?'#5fcb52':'#ff5048');
      g.fillStyle=col;g.fillRect(x,y+8,3,3);
      g.fillStyle=col;g.globalAlpha=.4;g.fillRect(x-1,y+7,5,5);g.globalAlpha=1;
    }
    // Rack body texture lines
    g.fillStyle='rgba(60,200,255,.08)';g.fillRect(0,y,512,1);
    g.fillStyle='rgba(0,0,0,.55)';g.fillRect(0,y+27,512,1);
  }
  const t=new THREE.CanvasTexture(c);
  t.wrapS=THREE.RepeatWrapping;t.wrapT=THREE.RepeatWrapping;
  t.repeat.set(2,1);
  return t;
})();
// ── Tactical pad floor — for the tutorial range
const _padTex=(()=>{
  const c=document.createElement('canvas');c.width=256;c.height=256;
  const g=c.getContext('2d');
  g.fillStyle='#0e1018';g.fillRect(0,0,256,256);
  // Hex grid overlay
  g.strokeStyle='rgba(60,180,255,.35)';g.lineWidth=1;
  const hexR=24,hexW=hexR*Math.sqrt(3);
  for(let q=-2;q<8;q++){
    for(let r=-2;r<8;r++){
      const cx=q*hexW+(r%2?hexW/2:0),cy=r*hexR*1.5;
      g.beginPath();
      for(let i=0;i<6;i++){
        const a=i*Math.PI/3+Math.PI/6;
        const x=cx+Math.cos(a)*hexR,y=cy+Math.sin(a)*hexR;
        if(i===0)g.moveTo(x,y);else g.lineTo(x,y);
      }
      g.closePath();g.stroke();
    }
  }
  // Big center cyan ring
  g.strokeStyle='rgba(80,200,255,.55)';g.lineWidth=3;
  g.beginPath();g.arc(128,128,90,0,Math.PI*2);g.stroke();
  const t=new THREE.CanvasTexture(c);
  t.wrapS=THREE.RepeatWrapping;t.wrapT=THREE.RepeatWrapping;
  t.repeat.set(3,5);
  return t;
})();
// ── Authored AA texture loader ────────────────────────────────────────────
// Each authored texture set lives under public/assets/materials/<name>/, with
// files named <name>-albedo.png (or .jpg), <name>-normal.jpg, <name>-roughness.jpg,
// <name>-metalness.jpg, and <name>-ao.jpg (jpg or png). Add a material to
// AA_AUTHORED_MATERIALS below and drop the files into the matching folder;
// no other code changes required. Missing files (or whole sets) fall back to
// the procedural path in materialLibrary.js — partial drops are safe.
const _AA_TEX_LOADER=new THREE.TextureLoader();
function _aaLoadTex(path,{isColor=false,repeat=3,channel=0}={}){
  const t=_AA_TEX_LOADER.load(path,(tex)=>{
    tex.wrapS=THREE.RepeatWrapping;
    tex.wrapT=THREE.RepeatWrapping;
    tex.repeat.set(repeat,repeat);
    if(channel!==undefined)tex.channel=channel;
    finalizePbrSurfaceTexture(THREE,tex,isColor);
    try{
      if(typeof renderer!=='undefined'&&renderer&&renderer.capabilities){
        const mx=renderer.capabilities.getMaxAnisotropy();
        tex.anisotropy=Math.min(mx,Math.max(tex.anisotropy||0,12));
        tex.needsUpdate=true;
      }
    }catch(_){}
  },undefined,err=>console.warn('[aa-texture] failed to load',path,err));
  t.wrapS=THREE.RepeatWrapping;
  t.wrapT=THREE.RepeatWrapping;
  t.repeat.set(repeat,repeat);
  if(channel!==undefined)t.channel=channel;
  return t;
}
