  const moodM=new THREE.MeshBasicMaterial({color:moodCol,transparent:true,opacity:.78,blending:THREE.AdditiveBlending});
  const fixedMood=bn===1?[[0,18.2],[-4.5,14.2],[5.0,5.4],[-14.2,1.0],[14.2,-2.2],[-5.0,-9.6],[0,-20.4]]:null;
