	    const t=this.tactic||ENEMY_TACTICS.soldier;
	    let reason=null;
	    const currentRisk=this.coverSlot?_coverSlotRisk(this.coverSlot,pp,walls):1;
	    if(woundedRetreat&&this.type!=='heavy'&&this.type!=='riot')reason='wounded';
	    else if(squadCover&&Math.random()<THREE.MathUtils.clamp(((squadDirective.coverBias||0)-.36)*1.35+(squadDirective.state==='regroup'?.18:0),.16,.84))reason=squadDirective.state==='regroup'?'squad-regroup':'squad-anchor';
