    const fifthNote=MUSIC.scale[(bar+4)%MUSIC.scale.length];
    const f3=MUSIC.rootHz*Math.pow(2,thirdNote/12);
    const f5=MUSIC.rootHz*Math.pow(2,fifthNote/12);
