function _triggerKnifePairBeat(kind){
  const pair=MELEE.pair;
  if(!pair||!pair.target)return;
  try{_sfxKnifePairBeat(kind);}catch(_){}
  const victim=pair.target._knifePairVictim;
  if(victim){
    if(kind==='grab')victim.grabPulse=Math.max(victim.grabPulse||0,1);
    if(kind==='slice')victim.slicePulse=Math.max(victim.slicePulse||0,1);
    if(kind==='impact')victim.impactPulse=Math.max(victim.impactPulse||0,1);
    if(kind==='rip')victim.ripPulse=Math.max(victim.ripPulse||0,1);
  }
  const rig=_ensureKnifePairContactRig();
  if(rig&&rig.userData){
    if(kind==='grab')rig.userData.grabPulse=Math.max(rig.userData.grabPulse||0,.85);
    if(kind==='slice'||kind==='impact')rig.userData.impactPulse=Math.max(rig.userData.impactPulse||0,1);
    if(kind==='rip')rig.userData.ripPulse=Math.max(rig.userData.ripPulse||0,1);
  }
  const side=pair.side||1;
  if(kind==='grab'){
    PP.shakeX+=side*.032;PP.shakeY-=.040;
    P._knifePairGrabPulse=Math.max(P._knifePairGrabPulse||0,1);
  }else if(kind==='slice'){
    PP.shakeX+=side*.070;PP.shakeY-=.090;
    P._knifePairSlicePulse=Math.max(P._knifePairSlicePulse||0,1);
  }else if(kind==='impact'){
    PP.shakeX-=side*.090;PP.shakeY-=.130;
    P._knifePairImpactPulse=Math.max(P._knifePairImpactPulse||0,1);
  }else if(kind==='rip'){
    PP.shakeX+=side*.050;PP.shakeY+=.030;
    P._knifePairRipPulse=Math.max(P._knifePairRipPulse||0,1);
  }
}
