function _updateCoreViewmodelPolishRuntime(dt,heatN){
  const ads=THREE.MathUtils.clamp(P.adsVis||P.ads||0,0,1);
  const adsSettle=THREE.MathUtils.smoothstep(ads,.12,.92);
  const hot=THREE.MathUtils.clamp(Number(heatN)||0,0,1);
  const pulse=.92+Math.sin((H.reticlePhase||0)*5.5)*.045;
  const aimSnap=buildAimFeelSnapshot(P,_aimFeelOptionsFor(P,K,RECOIL_STATE,_currentOpticProfile()));
  const aimDot=THREE.MathUtils.clamp(aimSnap.dotAlpha||1,.32,1);
  const aimSettle=THREE.MathUtils.clamp((aimSnap.readiness||0)*.70+(aimSnap.settlePulse||0)*.30,0,1);
  const aimConfidence=THREE.MathUtils.clamp(aimSnap.reticleConfidence||aimSettle,0,1);
  const lensFocus=THREE.MathUtils.clamp(aimSnap.lensFocus||aimSettle,0,1);
  const scopeShadow=THREE.MathUtils.clamp(aimSnap.scopeShadow||0,0,1);
  if(m4HeatM){
    m4HeatM.emissive.setRGB(hot*1.10,hot*.34,hot*.055);
    if(m4HeatM.specular)m4HeatM.specular.setRGB(.22+hot*.28,.24+hot*.14,.30+hot*.04);
    if('shininess' in m4HeatM)m4HeatM.shininess=122+hot*46;
  }
  if(m4ReticleM){
    const reticleOpacity=THREE.MathUtils.clamp((.68*pulse*(1+adsSettle*.22)+hot*.05+aimConfidence*.18-scopeShadow*.16)*aimDot,.12,1);
    m4ReticleM.opacity=reticleOpacity;
    if(m4ReticleHaloM)m4ReticleHaloM.opacity=THREE.MathUtils.clamp((.15+adsSettle*.16+hot*.08+aimConfidence*.14-scopeShadow*.08)*pulse,.06,.68);
    if(gReticle)gReticle.scale.setScalar(1+adsSettle*.36+hot*.12-aimConfidence*.08+scopeShadow*.06);
    if(gReticleHalo)gReticleHalo.scale.setScalar(1+adsSettle*.46+hot*.14+aimSettle*.06+scopeShadow*.10);
  }
  if(pistolOpticReticleM){
    const reticleOpacity=THREE.MathUtils.clamp((.74*pulse*(1+adsSettle*.14)+hot*.04+aimConfidence*.16-scopeShadow*.10)*aimDot,.34,.99);
    pistolOpticReticleM.opacity=reticleOpacity;
    if(pistolOpticHaloM)pistolOpticHaloM.opacity=gPistolReticleHalo&&gPistolReticleHalo.visible?THREE.MathUtils.clamp((.10+adsSettle*.08+hot*.04+aimConfidence*.08-scopeShadow*.04)*pulse,.05,.36):0;
    if(gPistolReticle)gPistolReticle.scale.setScalar(1);
    if(gPistolReticleHalo)gPistolReticleHalo.scale.setScalar(1);
  }
  if(pistolOpticGrp&&pistolOpticGrp.visible){
    pistolOpticGrp.traverse(o=>{
      if(o.userData&&o.userData.hideWhenAds&&o.visible!==undefined)o.visible=ads<.42;
    });
  }
  const lensOpacity=THREE.MathUtils.clamp(.46+adsSettle*.06+hot*.04+lensFocus*.08-scopeShadow*.08,.34,.68);
  if(m4LensM_active){
    m4LensM_active.opacity=lensOpacity;
    if(m4LensM_active.emissive)m4LensM_active.emissive.setRGB(.035+adsSettle*.10+hot*.035+lensFocus*.035,.075+adsSettle*.22+hot*.05+lensFocus*.070,.052+adsSettle*.15+hot*.025+lensFocus*.045);
    if('shininess' in m4LensM_active)m4LensM_active.shininess=218+adsSettle*32+lensFocus*34;
  }
  if(pistolOpticLensM){
    // Clear-glass window: barely-there tint that relaxes further as the sight
    // settles, so the world through the lens stays as bright as the world around it.
    pistolOpticLensM.opacity=THREE.MathUtils.clamp(.10-adsSettle*.03+hot*.01+lensFocus*.02-scopeShadow*.02,.05,.14);
    if(pistolOpticLensM.emissive)pistolOpticLensM.emissive.setRGB(.010+hot*.010,.020+adsSettle*.03+lensFocus*.02,.028+adsSettle*.04+lensFocus*.025);
    if('shininess' in pistolOpticLensM)pistolOpticLensM.shininess=220+adsSettle*30+lensFocus*30;
  }
  // Baked optic glass must stay CLEAR: a fraction of the old emissive drive is kept
  // as a faint coating sheen. Full strength rendered the DMR/AWM/MP9 lenses as
  // glowing opaque teal slabs.
  const opticGlow=(.15+adsSettle*.28+hot*.08+lensFocus*.14-scopeShadow*.08)*pulse*.12;
  const polishLens=(mat,r,g,b)=>{
    if(!mat||!mat.emissive)return;
    mat.emissive.setRGB(r*opticGlow,g*opticGlow,b*opticGlow);
    if('shininess' in mat)mat.shininess=220+adsSettle*46;
    if(mat.transparent!==true||mat.depthWrite){mat.transparent=true;mat.depthWrite=false;mat.needsUpdate=true;}
    if(!(mat.opacity<=.20))mat.opacity=.18;
  };
  polishLens(dmrLensM,.10,.56,.88);
  polishLens(snLensM,.08,.50,.82);
  _CORE_VISUAL_VIEWMODEL_POLISH_STATS.lastRuntime={
    heat:Number(hot.toFixed(3)),
    ads:Number(adsSettle.toFixed(3)),
    aimConfidence:Number(aimConfidence.toFixed(3)),
    lensFocus:Number(lensFocus.toFixed(3)),
    scopeShadow:Number(scopeShadow.toFixed(3)),
    opticGlow:Number(opticGlow.toFixed(3)),
    lensOpacity:Number(lensOpacity.toFixed(3))
  };
  gunGrp.userData.coreVisualViewmodelRuntime=_CORE_VISUAL_VIEWMODEL_POLISH_STATS.lastRuntime;
  return _CORE_VISUAL_VIEWMODEL_POLISH_STATS.lastRuntime;
}
let _smgIronsSuppressed=false;
function _syncPracticalIronSightViewmodel(){
  if(typeof P==='undefined')return;
  const ads=THREE.MathUtils.clamp(P.adsVis||P.ads||0,0,1);
  // A mounted pickup optic replaces the MP9 irons (they would poke through the lens).
  if(P.weaponIdx===4&&typeof SM_IRON_SIGHT_MESHES!=='undefined'){
    const showIrons=!_smgIronsSuppressed;
    for(const s of SM_IRON_SIGHT_MESHES)if(s&&s.visible!==showIrons)s.visible=showIrons;
    if(!showIrons&&typeof _AA_WEAPON_SURFACE_PARTS!=='undefined'){
      for(const d of _AA_WEAPON_SURFACE_PARTS)if(d&&d.userData.adsSightPaint&&d.userData.aaWeaponGroup===SM_MESHES&&d.visible)d.visible=false;
    }
  }
  const shotgunAds=P.weaponIdx===3&&ads>.62&&!P.reloading&&!P.vaulting&&!P.dropkickActive;
  for(const m of [sgStock,sgPad,sgComb,sgShellHldr,sgShellSlot]){
    if(m)m.visible=P.weaponIdx===3&&!shotgunAds;
  }
  const smgAds=P.weaponIdx===4&&ads>.55&&!P.reloading&&!P.vaulting&&!P.dropkickActive;
  for(const m of [smStock,smStockBack]){
    if(m)m.visible=P.weaponIdx===4&&!smgAds;
  }
}
