function _setMuzzlePos(x,y,z){_setMuzzlePosForSlot(0,x,y,z);}
function _setMuzzlePosForWeaponSlot(slot,idx){
  idx=normalizeWeaponIdx(idx,START_WEAPON_IDX);
  if(idx===0)_setMuzzlePosForSlot(slot,0,.030,-.49);
  else if(idx===1)_setMuzzlePosForSlot(slot,0,.026,-.15);
  else if(idx===3)_setMuzzlePosForSlot(slot,0,.034,-.52);
  else if(idx===4)_setMuzzlePosForSlot(slot,0,.010,-.40);
  else if(idx===5)_setMuzzlePosForSlot(slot,0,.030,-.51);
  else if(idx===6)_setMuzzlePosForSlot(slot,0,.046,-.30);
  else if(idx===7)_setMuzzlePosForSlot(slot,0,.030,-.62);
}
function _pulseMuzzleFlashForSlot(slot,suppressedMul=1){
  const p2=(slot|0)===1;
  const light=p2?muzzleLightP2:muzzleLight;
  const mat=p2?_pmfMatP2:_pmfMat;
  const diag=p2?_pmfD2:_pmfD;
  if(!light||!mat)return;
  const st=_muzzleFlashPulseState[p2?1:0];
  st.dur=suppressedMul<.5?.040:.064;
  st.t=st.dur;
  st.intensity=(5.8+(Math.random()*2.0))*suppressedMul;
  st.opacity=0.92*suppressedMul;
  light.intensity=st.intensity;
  mat.opacity=st.opacity;
  if(mat.color)mat.color.setHex(0xfff0b0);
  if(diag)diag.rotation.z=Math.PI*.25+Math.random()*.55;
}
function _tickMuzzleFlashForSlot(slot,dt){
  const p2=(slot|0)===1;
  const st=_muzzleFlashPulseState[p2?1:0];
  const light=p2?muzzleLightP2:muzzleLight;
  const mat=p2?_pmfMatP2:_pmfMat;
  if(!st||!light||!mat)return;
  if(st.t>0){
    st.t=Math.max(0,st.t-dt);
    const k=THREE.MathUtils.clamp(st.t/Math.max(.001,st.dur),0,1);
    const glow=k*k;
    light.intensity=st.intensity*glow;
    mat.opacity=st.opacity*k;
  }else if(light.intensity!==0||mat.opacity!==0){
    light.intensity=0;
    mat.opacity=0;
  }
}
function _tickMuzzleFlashes(dt){
  _tickMuzzleFlashForSlot(0,dt);
  if(typeof P2!=='undefined')_tickMuzzleFlashForSlot(1,dt);
}
