function _suppressLegacyViewmodelHandBlockout(root,label){
  if(!root||!root.traverse)return {version:'first-person-hand-dedupe.v1',label,hidden:0};
  let hidden=0,kept=0;
  root.traverse(o=>{
    if(!o||!o.isMesh)return;
    if(o.userData&&o.userData.aaViewmodelShell){kept++;return;}
    o.visible=false;
    o.userData.legacyViewmodelBlockoutSuppressed=true;
    o.userData.legacyViewmodelBlockoutReason='aa-shell-replaces-blockout';
    hidden++;
  });
  root.userData.legacyViewmodelBlockoutSuppression={version:'first-person-hand-dedupe.v1',label,hidden,kept};
  return root.userData.legacyViewmodelBlockoutSuppression;
}
const _VIEWMODEL_HAND_DEDUPE={
  version:'first-person-hand-dedupe.v1',
  right:_suppressLegacyViewmodelHandBlockout(rGrp,'right-hand'),
  left:_suppressLegacyViewmodelHandBlockout(lGrp,'left-support-hand')
};
