  4:{dim:[.023,.076,.029],pos:[-.002,-.034,-.030],rx:.22},
  5:{dim:[.029,.076,.038],pos:[-.002,-.036,-.032],rx:.22},
  6:{dim:[.034,.052,.046],pos:[-.002,-.028,-.028],rx:.20},
  7:{dim:[.029,.056,.038],pos:[-.002,-.030,-.030],rx:.22},
