  const W=(WEAPONS[P.weaponIdx]||WEAPONS[0]);
  const spec=getReloadTimelineSpec(P.weaponIdx);
  const phaseName=reloadPhaseLabel(rt,P.weaponIdx).toUpperCase();
  const signal=_holoSignal();
  const phasePulse=Math.max(signal.reloadPhasePulse||0,signal.reloadPulse||0);
  _drawHoloBackplate(g,c,{
    accent:'#40c8ff',
    accentSoft:'rgba(64,200,255,.13)',
    accent2:signal.criticalAmmo?'#ff6048':'#ffd060',
    bg0:'rgba(8,18,32,.96)',
    bg1:'rgba(5,10,22,.95)',
    phaseOffset:.33,
    signal
  });
  _holoText(g,'RELOAD',18,24,'900 20px Rajdhani, sans-serif','#ffd060','rgba(255,208,96,.58)');
  _holoText(g,phaseName,c.width-18,24,'800 13px Rajdhani, sans-serif',phasePulse>.18?'#ffd060':'#40c8ff','rgba(64,200,255,.55)','right');
  _drawHoloStatusPill(g,18,60,c.width-36,signal,'#40c8ff','#ffd060');
  _holoText(g,(W.name||'WEAPON').toUpperCase(),c.width/2,52,'700 11px Rajdhani, sans-serif','rgba(222,242,255,.72)','rgba(64,200,255,.32)','center');
  const magX=c.width/2-40,magY=88,magW=80,magH=82;
  g.save();
  g.strokeStyle='rgba(255,248,224,.84)';
  g.lineWidth=3;
  g.shadowColor='rgba(255,208,96,.38)';
  g.shadowBlur=8;
  g.beginPath();
  g.moveTo(magX+10,magY);
  g.lineTo(magX+magW-10,magY);
  g.lineTo(magX+magW-17,magY+magH);
  g.lineTo(magX+17,magY+magH);
  g.closePath();
  g.stroke();
  g.shadowBlur=0;
  const segs=9;
  const filled=Math.round((safeCurr/safeMag)*segs);
  for(let i=0;i<segs;i++){
    const lit=i<filled;
    g.fillStyle=lit?'rgba(255,208,96,.92)':'rgba(255,255,255,.10)';
    g.fillRect(magX+18,magY+magH-14-i*8,magW-36,4);
  }
  g.strokeStyle='rgba(64,200,255,.22)';
  g.beginPath();
  g.moveTo(magX+magW+12,magY+8);
  g.lineTo(magX+magW+12,magY+magH-8);
  g.stroke();
  g.restore();
  _holoText(g,'ROUNDS',c.width/2,194,'800 12px Rajdhani, sans-serif','rgba(255,255,255,.50)','rgba(255,208,96,.25)','center');
  _holoText(g,String(safeCurr).padStart(2,'0'),c.width/2,232,'900 58px Rajdhani, sans-serif','#fff8e0','rgba(255,208,96,.72)','center');
  _holoText(g,'/ '+safeMag,c.width/2,270,'800 21px Rajdhani, sans-serif','rgba(255,255,255,.60)','rgba(64,200,255,.30)','center');
