  g.stroke();
  g.strokeStyle='#40c8ff';
  g.shadowColor='rgba(64,200,255,.70)';
  g.shadowBlur=8;
  g.beginPath();
  g.arc(cx,cy,r,Math.PI*.75,Math.PI*.75+visual*Math.PI*1.5,false);
  g.stroke();
  g.restore();
  _holoText(g,Math.round(visual*100)+'%',cx,316,'900 18px Rajdhani, sans-serif','#ffffff','rgba(64,200,255,.50)','center');
  const railX=24,railY=354,railW=c.width-48;
