    gunGrp.position.y=_softClampRootValue(gunGrp,'y',gunGrp.position.y,target.y-yDown,target.y+yUp,alpha,clamps);
    gunGrp.position.z=_softClampRootValue(gunGrp,'z',gunGrp.position.z,target.z-zFwd,target.z+zBack,alpha,clamps);
    gunGrp.rotation.x=_softClampRootValue(gunGrp,'rx',gunGrp.rotation.x,target.rx-rxDown,target.rx+rxUp,alpha,clamps);
    gunGrp.rotation.y=_softClampRootValue(gunGrp,'ry',gunGrp.rotation.y,target.ry-ryWin,target.ry+ryWin,alpha,clamps);
