    before:before?{x:Number(before.x.toFixed(4)),y:Number(before.y.toFixed(4)),z:Number(before.z.toFixed(4)),rx:Number(before.rx.toFixed(4)),ry:Number(before.ry.toFixed(4)),rz:Number(before.rz.toFixed(4)),s:Number(before.s.toFixed(3))}:null,
    after:(()=>{const p=_viewmodelRootPoseSnapshot(gunGrp);return p?{x:Number(p.x.toFixed(4)),y:Number(p.y.toFixed(4)),z:Number(p.z.toFixed(4)),rx:Number(p.rx.toFixed(4)),ry:Number(p.ry.toFixed(4)),rz:Number(p.rz.toFixed(4)),s:Number(p.s.toFixed(3))}:null;})()
