let _quickThrowCD=0;
// ── PISTOL-WHIP + EXECUTION ──────────────────────────────────────────────────
const PISTOL_WHIP_FEEL={dur:.64,impactAt:.255,recoverAt:.420,cooldown:.50,range:1.90};
const GUN_BASH_CHOREOGRAPHY_VERSION='gun-bash-choreography.v1';
