  _uiSetStyleProperty(root,'high-class-feel','--high-class-ring-alpha',THREE.MathUtils.clamp((feel.polish||0)*.28+(feel.confirm||0)*.18-(feel.pressure||0)*.08,0,.42).toFixed(3));
  _uiSetStyleProperty(root,'high-class-feel','--high-class-ring-scale',(1-(feel.settle||0)*.035+(feel.pressure||0)*.030).toFixed(3));
  _uiSetClass(document.body,'high-class-feel','high-class-composed',(feel.composure||0)>.48&&(feel.pressure||0)<.50);
  _uiSetClass(document.body,'high-class-feel','high-class-flow',(feel.flow||0)>.22||(feel.targetFlow||0)>.18);
  _uiSetClass(document.body,'high-class-feel','high-class-pressure',(feel.pressure||0)>.42||(feel.noise||0)>.38);
  P._highClassFeelSnapshot=feel;
  return feel;
