    dead=!!P.dead;menu=!!G.menuOpen;deathcam=!!DEATHCAM.active;kill=Math.min(1,(_killCamT||0)/Math.max(.001,_killCamDur||1));setKind=SETPIECE&&SETPIECE.kind;setActive=!!(SETPIECE&&SETPIECE.active);
