function announce(txt,sub,dur){$e('wa-text').textContent=txt;$e('wa-sub').textContent=sub||'';$e('wave-announce').style.opacity='1';setTimeout(()=>$e('wave-announce').style.opacity='0',dur||2600);}
// ── FX / TRAILS ──────────────────────────────────────────────────────────────
const _Y_AXIS=new THREE.Vector3(0,1,0);
const _TRAIL_LEN_DIR=new THREE.Vector3();
const _TRAIL_ALIGN_DIR=new THREE.Vector3();
const _TRAIL_ALIGN_Q=new THREE.Quaternion();
const _NEAR_MISS_AIR_TMP={
  right:new THREE.Vector3(),
  up:new THREE.Vector3(),
  fwd:new THREE.Vector3(),
  pos:new THREE.Vector3()
};
function _alignCyl(mesh,from,to){
  const dir=_TRAIL_ALIGN_DIR.copy(to).sub(from);
  if(dir.lengthSq()<1e-8)return;
  _TRAIL_ALIGN_Q.setFromUnitVectors(_Y_AXIS,dir.normalize());
  mesh.quaternion.copy(_TRAIL_ALIGN_Q);
  mesh.position.copy(from).add(to).multiplyScalar(.5);
}
function addTrail(from,to,opts={}){
  const dir=_TRAIL_LEN_DIR.copy(to).sub(from);const len=dir.length();if(len<.05)return;
  const am=_additiveVfxTierMul();
  const focusTrail=THREE.MathUtils.clamp(opts.focusLevel!=null?opts.focusLevel:(P._focusVisual||0),0,1);
  const haloColor=opts.haloColor!=null?opts.haloColor:(focusTrail>.04?0x74eaff:0xffd070);
  const coreColor=opts.coreColor!=null?opts.coreColor:(focusTrail>.04?0xf0ffff:0xfffce0);
  const trailLife=opts.life!=null?opts.life:(.16*(1+focusTrail*1.75));
  const haloRadius=(opts.haloRadius!=null?opts.haloRadius:.022)*(1+focusTrail*.55);
  const coreRadius=(opts.coreRadius!=null?opts.coreRadius:.006)*(1+focusTrail*.42);
  const haloOpacity=(opts.haloOpacity!=null?opts.haloOpacity:(.55+focusTrail*.20))*am;
  const coreOpacity=(opts.coreOpacity!=null?opts.coreOpacity:Math.min(1,.95+focusTrail*.05))*am;
  // Outer halo — thick, soft additive glow
  const matG=new THREE.MeshBasicMaterial({color:haloColor,transparent:true,opacity:haloOpacity,depthWrite:false,blending:THREE.AdditiveBlending});
  const mG=new THREE.Mesh(new THREE.CylinderGeometry(haloRadius,haloRadius,len,6,1,true),matG);
  _alignCyl(mG,from,to);scene.add(mG);
  // Inner core — bright white-yellow streak
  const matC=new THREE.MeshBasicMaterial({color:coreColor,transparent:true,opacity:coreOpacity,depthWrite:false,blending:THREE.AdditiveBlending});
  const mC=new THREE.Mesh(new THREE.CylinderGeometry(coreRadius,coreRadius,len,6,1,true),matC);
  _alignCyl(mC,from,to);scene.add(mC);
  G.trails.push({mesh:mG,mat:matG,timer:trailLife,maxTime:trailLife,isTracer:true,focusTracer:focusTrail,gunplayKind:opts.kind||'neutral',extra:[{mesh:mC,mat:matC}]});
}
function spawnNearMissAirCut(cam,side=1,strength=.7){
  if(!cam||STABLE_RENDERING_MODE)return;
  const am=_additiveVfxTierMul();
  const s=THREE.MathUtils.clamp(strength,.25,1.25);
  const right=_NEAR_MISS_AIR_TMP.right.set(1,0,0).applyQuaternion(cam.quaternion);
  const up=_NEAR_MISS_AIR_TMP.up.set(0,1,0).applyQuaternion(cam.quaternion);
  const fwd=_NEAR_MISS_AIR_TMP.fwd.set(0,0,-1).applyQuaternion(cam.quaternion);
  const pos=_NEAR_MISS_AIR_TMP.pos.copy(cam.position)
    .addScaledVector(fwd,.72+Math.random()*.36)
    .addScaledVector(right,(side||1)*(.22+Math.random()*.22))
    .addScaledVector(up,(Math.random()-.5)*.22);
  const mat=new THREE.MeshBasicMaterial({
    color:0xfff2c0,
    transparent:true,
    opacity:(.40+.22*s)*am,
    depthWrite:false,
    blending:THREE.AdditiveBlending,
    side:THREE.DoubleSide
  });
  const slash=new THREE.Mesh(new THREE.PlaneGeometry((.18+.12*s),(.012+.010*s)),mat);
  slash.position.copy(pos);
  slash.lookAt(cam.position);
  slash.rotation.z+=(side||1)*(.70+Math.random()*.45);
  scene.add(slash);
  G.trails.push({mesh:slash,mat,timer:.085+.040*s,maxTime:.085+.040*s,isFlash:true,gunplayKind:'near-miss-cut'});
}
function addParticle(pos,hs){
  const am=_additiveVfxTierMul();
  const nSpark=Math.max(1,Math.round((hs?4:2)*am));
  for(let i=0;i<nSpark;i++){
    const mat=new THREE.MeshBasicMaterial({color:hs?0xffee00:0xff7a30,transparent:true,opacity:Math.min(1,.88+.12*am),depthWrite:false,blending:THREE.AdditiveBlending});
    const mesh=new THREE.Mesh(new THREE.SphereGeometry(.024,4,4),mat);
    mesh.position.copy(pos);
    const vel=new THREE.Vector3((Math.random()-.5)*7,(Math.random()*.3+.1)*5,(Math.random()-.5)*7);
    scene.add(mesh);
    G.trails.push({mesh,mat,vel,timer:.30,maxTime:.30,isParticle:true});
  }
}
// Red blood mist on enemy hits — slower drift, subtractive feel via dark tone
function addBlood(pos,hs){
  const gm=typeof _goreMul==='function'?_goreMul():1.0;
  const am=_additiveVfxTierMul();
  const sprayCount=Math.max(1,Math.floor((hs?7:3)*gm*am));
  for(let i=0;i<sprayCount;i++){
    const mat=new THREE.MeshBasicMaterial({color:hs?0xa60810:0x661018,transparent:true,opacity:.85*am,depthWrite:false});
    const r=hs?(.035+Math.random()*.04):(.030+Math.random()*.03);
    const mesh=new THREE.Mesh(new THREE.SphereGeometry(r,5,4),mat);
    mesh.position.copy(pos);
    const sp=hs?5.5:3.5;
    const vel=new THREE.Vector3((Math.random()-.5)*sp,(Math.random()-.1)*sp*.85,(Math.random()-.5)*sp);
    scene.add(mesh);
    G.trails.push({mesh,mat,vel,timer:hs?.85:.55,maxTime:hs?.85:.55,isBlood:true});
  }
  // Arterial mist puff for headshots — extra fine particles
  if(hs){
    const nMist=Math.max(2,Math.round(4*am));
    for(let i=0;i<nMist;i++){
      const mat=new THREE.MeshBasicMaterial({color:0xc8202c,transparent:true,opacity:.55*am,depthWrite:false,blending:THREE.AdditiveBlending});
      const mesh=new THREE.Mesh(new THREE.SphereGeometry(.02+Math.random()*.04,4,3),mat);
      mesh.position.copy(pos);
      const vel=new THREE.Vector3((Math.random()-.5)*4,Math.random()*3,(Math.random()-.5)*4);
      scene.add(mesh);
      G.trails.push({mesh,mat,vel,timer:.40,maxTime:.40,isSmoke:true});
    }
  } else {
    // Phase AB: body-shot mist — softer + shorter than headshot mist but
    // still gives the hit a "puff" tell. Skipped at low gore tier.
    if(typeof _goreMul==='function'&&_goreMul()>=1.0&&Math.random()<.45){
      const nb=Math.max(1,Math.round(2*am));
      for(let i=0;i<nb;i++){
        const mat=new THREE.MeshBasicMaterial({color:0x801018,transparent:true,opacity:.40*am,depthWrite:false});
        const mesh=new THREE.Mesh(new THREE.SphereGeometry(.018+Math.random()*.024,4,3),mat);
        mesh.position.copy(pos);
        const vel=new THREE.Vector3((Math.random()-.5)*2.4,Math.random()*1.6,(Math.random()-.5)*2.4);
        scene.add(mesh);
        G.trails.push({mesh,mat,vel,timer:.30,maxTime:.30,isSmoke:true});
      }
    }
  }
}
