  const pickup={att:null,grp,halo,haloM,beam,beamM,bodyM,accentM,lensM:accentM,mountM:bodyM,phase:Math.random()*Math.PI*2,baseY:grp.position.y,isAmmoPack:true};
  G.pickups.push(pickup);
