const rc=new THREE.Raycaster();rc.far=80;
const _rcShared=new THREE.Raycaster();
const _aimHudDir=new THREE.Vector3();
const ENEMY_SHOT_TMP={
  right:new THREE.Vector3(),
  up:new THREE.Vector3(),
  fwd:new THREE.Vector3(),
  toCam:new THREE.Vector3(),
  target:new THREE.Vector3(),
  dir:new THREE.Vector3(),
  start:new THREE.Vector3(),
  end:new THREE.Vector3(),
  jitter:new THREE.Vector3(),
  hitRight:new THREE.Vector3()
};
const _PLAYER_MOVE_CELL_CACHE={seen:[-1,-1,-1],cellsHit:[]};
function _aimRayDir(out=new THREE.Vector3()){
  return out.set(0,0,-1).applyQuaternion(camera.quaternion).normalize();
}
function _aimRayDirWithSpread(sp,out=new THREE.Vector3()){
  return out.set((Math.random()-.5)*sp,(Math.random()-.5)*sp,-1).normalize().applyQuaternion(camera.quaternion);
}
function _playerMoveCollisionStep(pl,walls,mx,mz){
  if(!pl||(!mx&&!mz))return;
  const R=PR,nx=pl.pos.x+mx,nz=pl.pos.z+mz;
  let okX=true,okZ=true;
  const _pIdx=(G.levelData&&G.levelData.wallIndex&&SETTINGS.raycastSpatialIndex!==false)?G.levelData.wallIndex:null;
  if(_pIdx){
    const cells=_pIdx.cells;
    const seenIds=_PLAYER_MOVE_CELL_CACHE.seen;
    const cellsHit=_PLAYER_MOVE_CELL_CACHE.cellsHit;
    seenIds[0]=-1;seenIds[1]=-1;seenIds[2]=-1;cellsHit.length=0;
    for(let j=0;j<3;j++){
      const tx=j===0?nx:pl.pos.x;
      const tz=j===1?nz:pl.pos.z;
      const ix=((tx-_pIdx.xMin)/_pIdx.cs)|0,iz=((tz-_pIdx.zMin)/_pIdx.cs)|0;
      if(ix<0||iz<0||ix>=_pIdx.nx||iz>=_pIdx.nz)continue;
      const id=ix+iz*_pIdx.nx;
      if(seenIds[0]===id||seenIds[1]===id||seenIds[2]===id)continue;
      if(seenIds[0]===-1)seenIds[0]=id;else if(seenIds[1]===-1)seenIds[1]=id;else seenIds[2]=id;
      const c=cells[id];if(c)cellsHit.push(c);
    }
    for(const c of cellsHit){
      for(let i=0,n=c.length;i<n;i++){
        const w=c[i];
        if(w.broken)continue;
        if(okX&&nx+R>w.x0&&w.x1>nx-R&&pl.pos.z+R>w.z0&&w.z1>pl.pos.z-R)okX=false;
        if(okZ&&pl.pos.x+R>w.x0&&w.x1>pl.pos.x-R&&nz+R>w.z0&&w.z1>nz-R)okZ=false;
        if(!okX&&!okZ)break;
      }
      if(!okX&&!okZ)break;
    }
  } else {
    for(const w of (walls||[])){
      if(w.broken)continue;
      if(nx+R>w.x0&&w.x1>nx-R&&pl.pos.z+R>w.z0&&w.z1>pl.pos.z-R)okX=false;
      if(pl.pos.x+R>w.x0&&w.x1>pl.pos.x-R&&nz+R>w.z0&&w.z1>nz-R)okZ=false;
    }
  }
  if(okX)pl.pos.x=nx;
  if(okZ)pl.pos.z=nz;
}
function _resolvePlayerMoveWithCollisionSubsteps(pl,walls,mx,mz){
  const startX=pl.pos.x,startZ=pl.pos.z;
  const len=Math.hypot(mx,mz);
  const steps=len>.32?Math.min(4,Math.ceil(len/.26)):1;
  const sx=mx/steps,sz=mz/steps;
  for(let i=0;i<steps;i++)_playerMoveCollisionStep(pl,walls,sx,sz);
  return Math.hypot(pl.pos.x-startX,pl.pos.z-startZ);
}
function _syncAimHud(){
  // The true fire ray is the camera center. Keep DOM HUD elements fixed at
  // their CSS center instead of reprojecting a point every frame; projection
  // math picked up FOV/breath/roll noise and made the crosshair shimmer.
  const x=$e('xhair'),hm=$e('hitmark');
  if(x&&(x.style.left||x.style.top)){x.style.left='';x.style.top='';}
  if(hm&&(hm.style.left||hm.style.top)){hm.style.left='';hm.style.top='';}
}
function _rayHits(origin,dir,near,far,targets){
  _rcShared.set(origin,dir);_rcShared.near=near||0;_rcShared.far=far||80;
  return _rcShared.intersectObjects(targets,false);
}
// ── HOLD BREATH — Shift+ADS holds breath for sniper precision (limited duration)
const BREATH={holding:false,timer:0,maxDur:4.0,cooldown:0,recoverRate:.6};
function tickBreath(dt){
  // Auto-engage if ADS + sprint key held + sniper/DMR equipped
  const sniperLike=P.weaponIdx===5||P.weaponIdx===7;
  const wantHold=K['ShiftLeft']&&P.ads>.5&&sniperLike&&!P.dead;
  if(wantHold&&BREATH.timer<BREATH.maxDur&&BREATH.cooldown<=0){
    BREATH.holding=true;
    BREATH.timer+=dt;
    if(BREATH.timer>=BREATH.maxDur){
      BREATH.holding=false;
      BREATH.cooldown=2.5; // 2.5s recovery
    }
  } else {
    BREATH.holding=false;
    if(BREATH.cooldown>0)BREATH.cooldown-=dt;
    else BREATH.timer=Math.max(0,BREATH.timer-dt*BREATH.recoverRate);
  }
  // Update HUD
  const hb=$e('breath-bar');
  if(hb){
    if(sniperLike&&P.ads>.5){
      hb.classList.add('show');
      const ratio=1-(BREATH.timer/BREATH.maxDur);
      hb.querySelector('.bb-fill').style.width=(ratio*100).toFixed(1)+'%';
      hb.querySelector('.bb-label').textContent=BREATH.cooldown>0?'CATCH BREATH':(BREATH.holding?'HOLDING':'SHIFT');
    } else {
      hb.classList.remove('show');
    }
  }
}
function isBreathHeld(){return BREATH.holding;}
// ── PER-SURFACE BULLET IMPACT EFFECTS — different visuals per building
function spawnSurfaceImpact(hitPt,normal,opts={}){
  const bn=G.building||1;
  const p=_surfaceVfxProfileForBuilding(bn);
  const incidence=(opts&&opts.dir&&normal)?Math.abs(opts.dir.dot(normal)):opts.incidence;
  const feel=buildSurfaceImpactFeelSnapshot(Object.assign({building:bn,incidence},opts));
  if(opts&&opts.fromPlayer&&P){
    P._surfaceImpactReadPulse=Math.max(P._surfaceImpactReadPulse||0,THREE.MathUtils.clamp((feel.playerReadPulse||0)*.82,0,.75));
    P._surfaceImpactHardnessPulse=Math.max(P._surfaceImpactHardnessPulse||0,THREE.MathUtils.clamp((feel.hardSnap||feel.materialKick||0)*.70,0,.80));
  }
  // Spawn sparks
  if(typeof spawnSparkBurst==='function'){
    spawnSparkBurst(hitPt,p.sparkCol,Math.max(1,Math.min(26,Math.round((p.sparkCount||4)*(feel.sparkMul||1)+(feel.microShardCount||0)*.35))),Object.assign({},p,{sparkStretch:(p.sparkStretch||1)*(feel.sparkMul||1)*(feel.sparkStretchMul||1),sparkLife:(p.sparkLife||.42)*(feel.sparkLifeMul||1)}));
  }
  // Spawn dust
  const dustCount=Math.max(1,Math.min(22,Math.round((p.dustCount||4)*(feel.dustMul||1)+(feel.microShardCount||0)*.45)));
  for(let i=0;i<dustCount;i++){
    const m=new THREE.MeshBasicMaterial({map:_vfxDustPuffTex,color:p.dustCol,transparent:true,opacity:(p.dustOpacity??.48)*Math.min(1.25,feel.dustMul||1),depthWrite:false,side:THREE.DoubleSide});
    const mesh=new THREE.Mesh(new THREE.PlaneGeometry((.09+Math.random()*.04)*Math.min(1.8,feel.dustMul||1),(.065+Math.random()*.03)*Math.min(1.8,feel.dustMul||1)),m);
    mesh.position.copy(hitPt);
    if(normal)mesh.position.addScaledVector(normal,.02);
    const roll=Math.random()*Math.PI;
    _orientVfxBillboard(mesh,camera,roll);
    const tan=new THREE.Vector3((Math.random()-.5),(Math.random()-.5),(Math.random()-.5));
    if(normal)tan.cross(normal).normalize();
    const vel=tan.multiplyScalar(1.2+Math.random()*1.5).add((normal||new THREE.Vector3(0,1,0)).clone().multiplyScalar(.45+(feel.dustLift||0)*.70));
    scene.add(mesh);
    const life=(p.dustLife||.55)*(feel.dustLifeMul||1)*(0.86+Math.random()*.22);
    G.trails.push({mesh,mat:m,timer:life,maxTime:life,isDust:true,vel,faceCameraBillboard:true,billboardRoll:roll,billboardRollSpeed:(Math.random()-.5)*(.9+(feel.decalJitter||0)*.45),opacityScale:p.dustOpacity??.48,growRate:1.55+(feel.materialKick||0)*.20,drag:.88,lift:.24+(feel.dustLift||0)*.18});
  }
  // Surface-specific sound
  const c=getAC();
  const sound=feel.sound||p.sound;
  const soundGain=THREE.MathUtils.clamp((feel.impact||1)*.82*(feel.audioGain||1),.28,1.65);
  const pitch=THREE.MathUtils.clamp(feel.audioPitch||1,.62,1.7);
  if(sound==='ping'){
    const o=c.createOscillator(),g=c.createGain();
    o.type='triangle';o.frequency.setValueAtTime((2400+Math.random()*400)*pitch,c.currentTime);
    o.frequency.exponentialRampToValueAtTime(800*pitch,c.currentTime+.18);
    g.gain.setValueAtTime(.18*soundGain,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.20);
    o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.22);
  } else if(sound==='thud'){
    const o=c.createOscillator(),g=c.createGain();
    o.type='sine';o.frequency.setValueAtTime(120*pitch,c.currentTime);
    o.frequency.exponentialRampToValueAtTime(60*pitch,c.currentTime+.10);
    g.gain.setValueAtTime(.20*soundGain,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.12);
    o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.14);
  } else if(sound==='chip'){
    const o=c.createOscillator(),g=c.createGain();
    o.type='triangle';o.frequency.setValueAtTime(1800*pitch,c.currentTime);
    o.frequency.exponentialRampToValueAtTime(900*pitch,c.currentTime+.10);
    g.gain.setValueAtTime(.15*soundGain,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.12);
    o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.14);
  } else if(sound==='shatter'){
    [2400,2800,3200].forEach((f,i)=>{
      const o=c.createOscillator(),g=c.createGain();
      o.type='triangle';o.frequency.value=f*pitch;
      g.gain.setValueAtTime(.10*soundGain,c.currentTime+i*.04);
      g.gain.exponentialRampToValueAtTime(.001,c.currentTime+i*.04+.10);
      o.connect(g);g.connect(c.destination);o.start(c.currentTime+i*.04);o.stop(c.currentTime+i*.04+.12);
    });
  }
  return feel;
}
// ── RICOCHET — steep-angle bullet hits on hard surfaces deflect
function _maybeRicochet(hitPt,dir,normal,opts={}){
  if(!normal)return null;
  const incidence=Math.abs(dir.dot(normal));
  const feel=buildSurfaceImpactFeelSnapshot(Object.assign({building:G&&G.building||1,incidence,dir},opts));
  // Steep angle (incidence < 0.30) — ricochet possible
  if(incidence>.42||Math.random()>THREE.MathUtils.clamp(feel.ricochetChance||0,0,.72))return null;
  // Reflect direction off normal
  const reflected=dir.clone().sub(normal.clone().multiplyScalar(2*dir.dot(normal)));
  // Add slight randomization
  reflected.x+=(Math.random()-.5)*.1;
  reflected.y+=(Math.random()-.5)*.1;
  reflected.z+=(Math.random()-.5)*.1;
  reflected.normalize();
  // Spawn spark + sound at ricochet point
  if(typeof spawnSparkBurst==='function')spawnSparkBurst(hitPt,0xfff060,Math.max(4,Math.round(8*(feel.sparkMul||1))));
  if(typeof sfxRicochet==='function')sfxRicochet();
  // Trace ricocheted bullet — hitscan to find its endpoint
  const rc2=new THREE.Raycaster(hitPt.clone().addScaledVector(reflected,.05),reflected,0,15);
  const meshes=G.enemyMgr?G.enemyMgr.getMeshes():[];
  const hits=rc2.intersectObjects(meshes,false);
  if(hits.length){
    const h=hits[0];
    const enemy=h.object.userData.enemy;
    const isHead=h.object.userData.isHead===true;
    // Reduced damage from ricochet
    const W=WEAPONS[P.weaponIdx];
    const dmg=(isHead?W.hsDmg:W.dmg)*.45;
    _primeEnemyHitFromObject(h.object,isHead?'head':'torso');
    const killed=enemy.takeDamage(dmg,isHead);
    if(typeof triggerPlayerHitImpactFeedback==='function')triggerPlayerHitImpactFeedback(h.point,isHead,killed,dmg,P.weaponIdx,0);
    if(typeof spawnDmgNumber==='function')spawnDmgNumber(h.point.clone().add(new THREE.Vector3(0,.4,0)),dmg,isHead,killed);
    if(typeof showHM==='function')showHM(killed?(isHead?'headkill':'kill'):(isHead?'head':'body'),Math.min(1.35,dmg/120));
    if(typeof sfxHit==='function')sfxHit(isHead);
    if(typeof sfxHitConfirm==='function')sfxHitConfirm(isHead,killed,Math.min(1.35,dmg/120));
    if(typeof _registerDmgDealt==='function')_registerDmgDealt(dmg);
    if(typeof addBlood==='function')addBlood(h.point,isHead);
    if(killed&&typeof killFeed==='function'){
      killFeed(isHead,{dist:hitPt.distanceTo(camera.position),wallbang:true});
      P.kills++;if(isHead)P.headshots++;
      comboKill(isHead,{source:'ricochet-kill',closeRange:THREE.MathUtils.clamp(1-hitPt.distanceTo(camera.position)/5,0,1)});
      applyStoryMomentumShock(enemy,h.point,{source:'ricochet-kill',isHead});
      attachToast('<div style="color:#ffd060;letter-spacing:.30em">▼ RICOCHET KILL</div>',2000);
      setTimeout(()=>checkZoneClears(),60);
    }
    addTrail(hitPt,h.point,{kind:'ricochet-hit',life:feel.ricochetTraceLife||.16,haloColor:0xfff060,coreColor:0xffffff,haloRadius:.018+(feel.hardSnap||0)*.006});
    if(P)P._lastSurfaceImpactFeel=feel;
    return h.point;
  }
  // No hit — show short trail
  const endPt=hitPt.clone().addScaledVector(reflected,Math.min(8,3+Math.random()*5));
  addTrail(hitPt,endPt,{kind:'ricochet',life:feel.ricochetTraceLife||.14,haloColor:0xffe080,coreColor:0xffffff,haloRadius:.016+(feel.hardSnap||0)*.006});
  if(P)P._lastSurfaceImpactFeel=feel;
  return null;
}
// ── LIMB HITS — detect legs/arms by hit Y/X coordinate vs enemy bbox
function _detectLimbHit(enemy,hitPt,isHead){
  if(isHead)return null;
  const ey=enemy.group.position.y;
  const ex=enemy.group.position.x;
  const ez=enemy.group.position.z;
  // Leg: hit below mid-thigh (~y < ey+0.45)
  if(hitPt.y<ey+.45)return 'leg';
  // Arm: hit far from torso center on horizontal plane — wider than vest
  // Need facing-relative offset
  const facingY=enemy.group.rotation.y;
  const localX=Math.cos(facingY)*(hitPt.x-ex)+Math.sin(facingY)*(hitPt.z-ez);
  if(Math.abs(localX)>.22&&hitPt.y>ey+.85&&hitPt.y<ey+1.25)return 'arm';
  return null; // torso
}
function _applyLimbEffect(enemy,limb){
  if(!enemy)return;
  const now=performance.now();
  if(limb==='leg'){
    enemy._legSlowedUntil=now+4000;
    enemy._legSlowMul=.50;
  } else if(limb==='arm'){
    enemy._armPenalizedUntil=now+5000;
    enemy._armAccuracyMul=.60;
  }
}
function _applyEnemyWoundedGameplayState(enemy,limbId='torso',damage=0,profile=null,isMelee=false){
  if(!enemy||enemy.dead)return null;
  const now=performance.now();
  const id=String(limbId||'torso');
  const prof=profile||enemy._hitReactionProfile||{};
  const flags=enemy._lastHitFlags||{};
  const closeKind=flags.closeCombat||'';
  const kind=/head|neck/i.test(id)?'head':/Thigh|Shin|leg/i.test(id)?'leg':/Arm|Forearm|arm/i.test(id)?'arm':'torso';
  const pairedKnife=!!flags.pairedKnife||closeKind==='knife_heavy_stab'||closeKind==='knife_slice';
  const severe=prof.impactClass==='break'||prof.severe||damage>=85||isMelee;
  const wounded01=THREE.MathUtils.clamp(1-(enemy.hp||0)/Math.max(1,enemy.maxHp||enemy.hp||1),0,1);
  const legPain=THREE.MathUtils.clamp((kind==='leg'?.48:0)+(prof.kneeBuckle||0)*.46+(prof.balanceLoss||0)*.38+wounded01*.22,0,1.25);
  const armPain=THREE.MathUtils.clamp((kind==='arm'?.54:0)+(prof.weaponDrop||0)*.40+(prof.weaponSlip||0)*.42+(prof.aimBreak||0)*.18+wounded01*.18,0,1.25);
  const bodyPain=THREE.MathUtils.clamp((kind==='torso'?.42:0)+(prof.torsoFold||0)*.34+(prof.guardClutch||0)*.28+wounded01*.20,0,1.20);
  const headPain=THREE.MathUtils.clamp((kind==='head'?.46:0)+(prof.headWhip||0)*.44+(prof.painLook||0)*.24,0,1.20);
  const pain=THREE.MathUtils.clamp(Math.max(legPain*.90,armPain*.84,bodyPain*.72,headPain*.70,wounded01*.42),0,1.25);
  const armorResist=(enemy.type==='heavy'||enemy.type==='riot'||enemy.type==='shielded'||enemy.type==='boss')?.78:1;
  const dur=Math.round((1700+pain*2800+(severe?1100:0)+(isMelee?700:0)+(pairedKnife?520:0))*armorResist);
  const moveMul=THREE.MathUtils.clamp(1-legPain*.42-bodyPain*.12-headPain*.08,enemy.type==='boss'?.58:.38,1);
  const strafeMul=THREE.MathUtils.clamp(1-legPain*.55-bodyPain*.10,enemy.type==='boss'?.62:.32,1);
  const accuracyMul=THREE.MathUtils.clamp(1-armPain*.46-headPain*.25-bodyPain*.10,enemy.type==='boss'?.50:.34,1);
  const fireDelayMul=THREE.MathUtils.clamp(1+armPain*.85+headPain*.46+bodyPain*.28+legPain*.14,1,2.45);
  const coverBias=THREE.MathUtils.clamp((prof.coverBreak||0)*.36+(prof.guardClutch||0)*.32+pain*.34,0,1);
  enemy._woundedGameplayUntil=Math.max(enemy._woundedGameplayUntil||0,now+dur);
  enemy._woundedGameplay={
    version:'enemy-wounded-gameplay.v1',
    source:pairedKnife?'knife-choreography':(isMelee?'close-combat':'gunfire'),
    closeCombat:closeKind||null,
    choreographyVersion:pairedKnife?KNIFE_CLOSE_CHOREOGRAPHY_VERSION:null,
    limbId:id,
    kind,
    severe:!!severe,
    pain:Number(pain.toFixed(3)),
    legPain:Number(legPain.toFixed(3)),
    armPain:Number(armPain.toFixed(3)),
    bodyPain:Number(bodyPain.toFixed(3)),
    headPain:Number(headPain.toFixed(3)),
    moveMul:Number(moveMul.toFixed(3)),
    strafeMul:Number(strafeMul.toFixed(3)),
    accuracyMul:Number(accuracyMul.toFixed(3)),
    fireDelayMul:Number(fireDelayMul.toFixed(3)),
    coverBias:Number(coverBias.toFixed(3)),
    msLeft:dur
  };
  if(legPain>.18){
    enemy._legSlowedUntil=Math.max(enemy._legSlowedUntil||0,now+dur);
    enemy._legSlowMul=Math.min(enemy._legSlowMul||1,moveMul);
    enemy._woundedLimpSide=/left/i.test(id)?-1:/right/i.test(id)?1:(prof.side||Math.sign(enemy.staggerDir&&enemy.staggerDir.x)||1);
  }
  if(armPain>.16){
    enemy._armPenalizedUntil=Math.max(enemy._armPenalizedUntil||0,now+dur+650);
    enemy._armAccuracyMul=Math.min(enemy._armAccuracyMul||1,accuracyMul);
    enemy._woundedFireDelayMul=Math.max(enemy._woundedFireDelayMul||1,fireDelayMul);
  }
  if(coverBias>.34){
    enemy._woundedCoverBias=Math.max(enemy._woundedCoverBias||0,coverBias);
    enemy._suppressedUntil=Math.max(enemy._suppressedUntil||0,now+Math.round(220+coverBias*420));
    enemy.peekCooldown=Math.max(enemy.peekCooldown||0,.14+coverBias*.32);
    enemy.peekAmtTarget=0;
  }
  if((severe||pain>.72)&&enemy.state===ATTACK&&enemy.type!=='boss'){
    enemy.repositionReason='wounded';
    enemy._woundedRetreatUntil=Math.max(enemy._woundedRetreatUntil||0,now+Math.round(520+pain*760));
  }
  const hpRatio=(enemy.hp||0)/Math.max(1,enemy.maxHp||enemy.hp||1);
  const finishable=enemy.type!=='boss'&&!enemy.isBoss&&(severe||pain>.78||hpRatio<.42||pairedKnife)&&hpRatio<=(pairedKnife?.78:.68);
  if(finishable){
    const finishDur=Math.round(900+pain*1900+(severe?650:0));
    enemy._finishableUntil=Math.max(enemy._finishableUntil||0,now+finishDur);
    enemy._finishableTakedown={
      version:'enemy-finishable-takedown.v1',
      limbId:id,
      kind,
      reason:severe?'severe-wound':hpRatio<.42?'low-health':'pain-window',
      pain:Number(pain.toFixed(3)),
      hpRatio:Number(hpRatio.toFixed(3)),
      msLeft:finishDur
    };
    enemy._storyReadabilityPulse=Math.max(enemy._storyReadabilityPulse||0,Math.min(1,pain*.55+.18));
    enemy.shootTimer=Math.max(enemy.shootTimer||0,.24+pain*.22);
    enemy.burstCooldown=Math.max(enemy.burstCooldown||0,.18+pain*.18);
    if(enemy.group&&enemy.group.userData)enemy.group.userData.finishableTakedown=enemy._finishableTakedown;
  }
  enemy._storyReadabilityPulse=Math.max(enemy._storyReadabilityPulse||0,Math.min(1,pain*.38+.10));
  enemy.shootTimer=Math.max(enemy.shootTimer||0,(fireDelayMul-1)*.18);
  enemy.burstCooldown=Math.max(enemy.burstCooldown||0,(fireDelayMul-1)*.14);
  enemy.aimReady=Math.max(0,(enemy.aimReady||0)-(1-accuracyMul)*.32);
  if(typeof recordEnemyCombatStressAnimationPolish==='function'){
    recordEnemyCombatStressAnimationPolish(enemy,{
      kind:finishable?'finishable':'wounded',
      strength:THREE.MathUtils.clamp(pain*.82+coverBias*.24+(severe?.18:0),0,1.75),
      side:enemy._woundedLimpSide||prof.side||Math.sign(enemy.staggerDir&&enemy.staggerDir.x)||1,
      nowMs:now
    });
  }
  if(enemy.group&&enemy.group.userData)enemy.group.userData.woundedGameplay=enemy._woundedGameplay;
  return enemy._woundedGameplay;
}
function _enemyMoveSpeedMul(enemy){
  if(!enemy)return 1.0;
  let mul=1.0;
  const nowMs=performance.now();
  const wounded=(enemy._woundedGameplayUntil&&nowMs<enemy._woundedGameplayUntil)?enemy._woundedGameplay:null;
  if(wounded&&Number.isFinite(wounded.moveMul))mul*=wounded.moveMul;
  const closeCombat=(enemy._closeCombatChoreographyUntil&&nowMs<enemy._closeCombatChoreographyUntil)?enemy._closeCombatChoreography:null;
  if(closeCombat){
    mul*=1-THREE.MathUtils.clamp((closeCombat.targetRootLock||0)*.18+(closeCombat.limbShock||0)*.10+(closeCombat.weaponJolt||0)*.08+(closeCombat.woundPressure||0)*.08,0,.42);
  }
  if(Number.isFinite(enemy._storySpeedMul))mul*=THREE.MathUtils.clamp(enemy._storySpeedMul,.70,1.24);
  if(enemy._squadDirective&&enemy._squadDirective.active&&Number.isFinite(enemy._squadDirective.speedMul))mul*=THREE.MathUtils.clamp(enemy._squadDirective.speedMul,.68,1.28);
  if(enemy._legSlowedUntil&&performance.now()<enemy._legSlowedUntil)mul*=enemy._legSlowMul||.50;
  const response=buildEnemyCombatResponseSnapshot(enemy,nowMs);
  if(response&&response.active){
    mul*=response.movementMul||1;
    const src=response.source||{};
    const recoveryDrag=THREE.MathUtils.clamp((src.rootDrag||0)*.22+(src.recoveryStep||0)*.18+(src.turnLock||0)*.10+(response.painTell||0)*.08+(response.weaponRecovery||0)*.06,0,.52);
    mul*=1-recoveryDrag;
    enemy._lastRecoveryMoveMul=mul;
    enemy._hitRecoveryLocomotion={
      version:'enemy-hit-recovery-locomotion.v1',
      rootDrag:src.rootDrag||0,
      recoveryStep:src.recoveryStep||0,
      turnLock:src.turnLock||0,
      painTell:response.painTell||0,
      weaponRecovery:response.weaponRecovery||0,
      shotInterrupt:response.shotInterrupt||0,
	      movementMul:response.movementMul||1,
	      wounded:wounded||null,
	      closeCombat:closeCombat||null,
	      finalMul:mul
	    };
  }else{
    enemy._lastRecoveryMoveMul=mul;
    enemy._hitRecoveryLocomotion=null;
  }
  enemy._combatResponseSnapshot=response;
  return Math.max(.22,Math.min(1.16,mul));
}
function _enemyAccuracyMul(enemy){
  let mul=1.0;
  const nowMs=performance.now();
  const wounded=(enemy&&enemy._woundedGameplayUntil&&nowMs<enemy._woundedGameplayUntil)?enemy._woundedGameplay:null;
  if(wounded&&Number.isFinite(wounded.accuracyMul))mul*=wounded.accuracyMul;
  const closeCombat=(enemy&&enemy._closeCombatChoreographyUntil&&nowMs<enemy._closeCombatChoreographyUntil)?enemy._closeCombatChoreography:null;
  if(closeCombat){
    mul*=1-THREE.MathUtils.clamp((closeCombat.enemyAimBreak||0)*.18+(closeCombat.enemyShotLock||0)*.12+(closeCombat.weaponJolt||0)*.08+(closeCombat.woundPressure||0)*.07,0,.46);
  }
  if(enemy&&enemy._squadDirective&&enemy._squadDirective.active&&Number.isFinite(enemy._squadDirective.accuracyMul))mul*=THREE.MathUtils.clamp(enemy._squadDirective.accuracyMul,.64,1.14);
  if(enemy._armPenalizedUntil&&nowMs<enemy._armPenalizedUntil)mul*=enemy._armAccuracyMul||.60;
  const response=buildEnemyCombatResponseSnapshot(enemy,nowMs);
  if(response&&response.active&&response.source){
	    mul*=1-THREE.MathUtils.clamp((response.source.turnLock||0)*.16+(response.source.weaponSlip||0)*.10+(response.shotInterrupt||0)*.12+(response.weaponRecovery||0)*.10,0,.46);
	    enemy._combatResponseSnapshot=response;
	  }
  return applyEnemyAnimationPolishAccuracy(enemy,mul,nowMs);
}
// ── CRITICAL HIT ZONES — back-of-head + neck = 3× damage
function _isCritHit(enemy,hitPt,isHead){
  if(!enemy)return {crit:false};
  // Calculate angle between player→enemy direction and enemy facing direction
  const facingY=enemy.group.rotation.y;
  const fwdX=Math.sin(facingY),fwdZ=Math.cos(facingY);
  const toEnemyX=enemy.group.position.x-camera.position.x;
  const toEnemyZ=enemy.group.position.z-camera.position.z;
  const len=Math.hypot(toEnemyX,toEnemyZ)||1;
  // Dot product: if player is BEHIND enemy (enemy facing away), dot is positive
  const dot=(toEnemyX*fwdX+toEnemyZ*fwdZ)/len;
  // Strong back-shot if dot > .6
  const fromBehind=dot>.6;
  if(isHead&&fromBehind)return {crit:true,type:'BACK_HEAD',mul:3.0};
  if(isHead)return {crit:false,type:'HEAD',mul:2.0}; // standard head already handled
  // Neck-area hit (just below head bbox center) = 2× crit
  const neckY=enemy.group.position.y+1.34;
  const distToNeck=Math.abs(hitPt.y-neckY);
  if(distToNeck<.10)return {crit:true,type:'NECK',mul:2.0};
  // Spine shot from behind (chest area, from back)
  if(fromBehind&&hitPt.y>enemy.group.position.y+0.85&&hitPt.y<enemy.group.position.y+1.10){
    return {crit:true,type:'SPINE',mul:1.7};
  }
  return {crit:false,mul:1.0};
}
// ── DAMAGE FALLOFF — per-weapon distance-vs-damage curve
// Each weapon has a {start, end, minMul} — full damage until `start` meters,
// linearly drops to `minMul` at `end` meters, stays at `minMul` beyond.
const DAMAGE_FALLOFF={
  0:{start:18,end:36,minMul:.55},  // M4 — drops past 18m
  1:{start:14,end:30,minMul:.50},  // Deagle
  3:{start:5, end:12,minMul:.30},  // Shotgun — drops fast
  4:{start:10,end:22,minMul:.45},  // SMG — short effective range
  5:{start:30,end:55,minMul:.75},  // DMR — holds well
  6:{start:14,end:28,minMul:.55},  // Suppressed Pistol
  7:{start:60,end:120,minMul:.90}  // Sniper — minimal falloff
};
function _falloffMul(weaponIdx,distance){
  const f=DAMAGE_FALLOFF[weaponIdx];
  if(!f)return 1.0;
  if(distance<=f.start)return 1.0;
  if(distance>=f.end)return f.minMul;
  const t=(distance-f.start)/(f.end-f.start);
  return 1.0+(f.minMul-1.0)*t;
}
// ── BALLISTIC PROJECTILES — for scoped precision rifles, bullets fly at finite speed
const PROJECTILES={list:[]};
const BALLISTICS={
  // weaponIdx → {speed (m/s), gravity (m/s²), enabled}
  5:{speed:680,gravity:6.0,enabled:true},   // DMR: 7.62 NATO
  7:{speed:920,gravity:9.0,enabled:true}    // Sniper: .338 LM, fast + drop
};
function spawnProjectile(originWorld,dir,weaponIdx,damageBase,damageHs,ownerSlot=0){
  const cfg=BALLISTICS[weaponIdx];
  if(!cfg||!cfg.enabled)return false;
  // Visible tracer mesh
  const trM=new THREE.MeshBasicMaterial({color:0xfff080,transparent:true,opacity:.85,blending:THREE.AdditiveBlending});
  const tr=new THREE.Mesh(new THREE.CylinderGeometry(.012,.012,.30,5,1,true),trM);
  // Orient cylinder along dir
  _alignCyl(tr,originWorld,originWorld.clone().addScaledVector(dir,.30));
  scene.add(tr);
  PROJECTILES.list.push({
    pos:originWorld.clone(),
    vel:dir.clone().multiplyScalar(cfg.speed),
    gravity:cfg.gravity,
    age:0,maxAge:2.5,
    weaponIdx,damageBase,damageHs,
    hitFlags:Object.assign({},Enemy._nextHitFlags||{weaponIdx}),
    mesh:tr,mat:trM,
    fromPlayer:true,
    ownerSlot:ownerSlot|0
  });
  return true;
}
function tickProjectiles(dt){
  if(!PROJECTILES.list.length)return;
  const meshes=G.enemyMgr?G.enemyMgr.getMeshes():[];
  for(let i=PROJECTILES.list.length-1;i>=0;i--){
    const p=PROJECTILES.list[i];
    const prev=p.pos.clone();
    p.age+=dt;
    // Apply gravity
    p.vel.y-=p.gravity*dt;
    // Move
    p.pos.addScaledVector(p.vel,dt);
    // Update visual
    if(p.mesh){
      _alignCyl(p.mesh,prev,p.pos);
      // Stretch the 0.30m tracer stub along local Y to cover the swept segment.
      const segLen=p.pos.distanceTo(prev);
      p.mesh.scale.set(1,Math.min(Math.max(1,segLen/0.30),60),1);
    }
    // Check enemy hits
    const segDir=p.pos.clone().sub(prev);
    const segLen=segDir.length();
    if(segLen>0.001){
      segDir.normalize();
      const segRay=new THREE.Raycaster(prev,segDir,0,segLen);
      const hits=segRay.intersectObjects(meshes,false);
      if(hits.length){
        const h=hits[0];
        const enemy=h.object.userData.enemy;
        const isHead=h.object.userData.isHead===true;
        // Apply damage
        const dmg=isHead?p.damageHs:p.damageBase;
        Enemy._nextHitFlags=p.hitFlags||{weaponIdx:p.weaponIdx};
        _primeEnemyHitFromObject(h.object,isHead?'head':'torso');
        if((p.ownerSlot|0)===0&&(isHead||dmg>120)&&typeof triggerHitStop==='function')triggerHitStop(isHead?44:34);
        const killed=enemy.takeDamage(dmg,isHead);
        const enemyResponse=enemy._combatResponseSnapshot||(enemy.group&&enemy.group.userData&&enemy.group.userData.combatDisruption)||null;
        const ownerPl=(p.ownerSlot|0)===1?P2:P;
        if(ownerPl){
          const pFeel=_weaponCombatProfile(p.weaponIdx);
          ownerPl.shotsHit=(ownerPl.shotsHit||0)+1;
          ownerPl._gunplayConfidence=Math.max(ownerPl._gunplayConfidence||0,isHead ? Math.max(.64,pFeel.confidenceHit||.48) : (pFeel.confidenceHit||.48));
          ownerPl._gunplayMissBloom=Math.max(0,(ownerPl._gunplayMissBloom||0)-.22);
          ownerPl._gunplayRhythm=Math.max(ownerPl._gunplayRhythm||0,.22);
          ownerPl._gunplayLastOutcome=isHead?'head':'hit';
          recordShotOutcomeFeedback(ownerPl,{hit:true,killed,headshot:isHead,damage:dmg,weaponIdx:p.weaponIdx,nowMs:performance.now()});
          recordGunplayOutcome(ownerPl,{hit:true,killed,headshot:isHead,damage:dmg,weaponIdx:p.weaponIdx,enemyResponse,nowMs:performance.now()});
        }
        if(typeof triggerPlayerHitImpactFeedback==='function')triggerPlayerHitImpactFeedback(h.point,isHead,killed,dmg,p.weaponIdx,p.ownerSlot||0);
        if(typeof spawnDmgNumber==='function')spawnDmgNumber(h.point.clone().add(new THREE.Vector3(0,.4,0)),dmg,isHead,killed);
        const markerBoost=(ownerPl&&ownerPl._gunplayShotQualitySnapshot&&ownerPl._gunplayShotQualitySnapshot.markerBoost)||1;
        if(typeof showHitMarkerForSlot==='function')showHitMarkerForSlot(p.ownerSlot||0,killed?(isHead?'headkill':'kill'):(isHead?'head':'body'),Math.min(1.55,(dmg/120)*markerBoost));
        if(typeof sfxHit==='function')sfxHit(isHead);
        if(typeof sfxHitConfirm==='function')sfxHitConfirm(isHead,killed,Math.min(1.45,dmg/120));
        if(typeof _registerDmgDealt==='function')_registerDmgDealt(dmg);
        if(typeof addBlood==='function')addBlood(h.point,isHead);
        if(killed){
          if((p.ownerSlot|0)===0&&typeof triggerHitStop==='function')triggerHitStop(isHead?46:36);
          if(typeof killFeed==='function')killFeed(isHead,{dist:p.pos.distanceTo(camera.position)});
          if(typeof awardKillMoney==='function')awardKillMoney(enemy,isHead);
          if(typeof comboKill==='function')comboKill(isHead,{source:'projectile-kill',closeRange:THREE.MathUtils.clamp(1-(p.pos.distanceTo(camera.position)/5),0,1)});
          if(typeof applyStoryMomentumShock==='function')applyStoryMomentumShock(enemy,h.point,{source:'projectile-kill',isHead});
          if(typeof _killKickFx==='function')_killKickFx(isHead);
          if(ownerPl){ownerPl.kills=(ownerPl.kills||0)+1;if(isHead)ownerPl.headshots=(ownerPl.headshots||0)+1;}
        }
        // Remove projectile
        scene.remove(p.mesh);if(p.mat)p.mat.dispose();if(p.mesh.geometry)p.mesh.geometry.dispose();
        PROJECTILES.list.splice(i,1);
        continue;
      }
      if(G.playMode==='duel'&&p.fromPlayer){
        const os=p.ownerSlot|0;
        const opp=os===1?P:P2;
        if(opp&&!opp.dead){
          const rsOpp=DUEL.respawnAt[os===0?1:0]||0;
          if(!(performance.now()<rsOpp)){
            const ro=prev;
            const rd=segDir;
            const jh=opp.jumpH||0;
            const cenH=new THREE.Vector3(opp.pos.x,EYE*0.92+jh,opp.pos.z);
            const cenB=new THREE.Vector3(opp.pos.x,EYE*0.48+jh,opp.pos.z);
            const tH=_raySphereHitT(ro,rd,cenH,0.28);
            const tB=_raySphereHitT(ro,rd,cenB,0.42);
            let tPv=null,hsPv=false;
            if(tH!=null&&(tB==null||tH<=tB)){tPv=tH;hsPv=true;}
            else if(tB!=null){tPv=tB;hsPv=false;}
            if(tPv!=null&&tPv<=segLen){
              const dmg=hsPv?p.damageHs:p.damageBase;
              duelApplyDamage(1-os,dmg);
              const ownerPl=os===1?P2:P;
              if(ownerPl){
                recordShotOutcomeFeedback(ownerPl,{hit:true,headshot:hsPv,damage:dmg,weaponIdx:p.weaponIdx,nowMs:performance.now()});
                recordGunplayOutcome(ownerPl,{hit:true,headshot:hsPv,damage:dmg,weaponIdx:p.weaponIdx,nowMs:performance.now()});
              }
              scene.remove(p.mesh);if(p.mat)p.mat.dispose();if(p.mesh.geometry)p.mesh.geometry.dispose();
              PROJECTILES.list.splice(i,1);
              continue;
            }
          }
        }
      }
    }
    // Check wall hit
    if(typeof wallRaycast==='function'){
      const wh=wallRaycast(prev,segDir);
      if(wh){
        const segDist=prev.distanceTo(wh.point);
        if(segDist<segLen){
          // Snap to wall
          if(typeof addImpact==='function'){
            const n=wh.face?wh.face.normal.clone().transformDirection(wh.object.matrixWorld):null;
            const surfaceFeel=addImpact(wh.point,n,{object:wh.object,weaponIdx:p.weaponIdx,distance:segDist,dir:segDir,fromPlayer:p.fromPlayer,source:'projectile'});
            if(p.fromPlayer){
              const ownerPl=(p.ownerSlot|0)===1?P2:P;
              if(ownerPl)ownerPl._lastSurfaceImpactFeel=surfaceFeel;
            }
          }
          if(p.fromPlayer){
            const ownerPl=(p.ownerSlot|0)===1?P2:P;
            const pFeel=_weaponCombatProfile(p.weaponIdx);
            if(ownerPl){
              const sFeel=ownerPl._lastSurfaceImpactFeel||{};
              ownerPl._gunplayMissBloom=Math.max(ownerPl._gunplayMissBloom||0,((sFeel.missBloom||.18))*(pFeel.missBloom||.30)/.30);
              ownerPl._gunplayConfidence=(ownerPl._gunplayConfidence||0)*THREE.MathUtils.clamp(1-(sFeel.confidenceLoss||.22),.64,.90);
              ownerPl._gunplayLastOutcome='surface';
              recordShotOutcomeFeedback(ownerPl,{hit:false,weaponIdx:p.weaponIdx,nowMs:performance.now()});
              recordGunplayOutcome(ownerPl,{hit:false,weaponIdx:p.weaponIdx,outcome:'surface',surface:sFeel,nowMs:performance.now()});
            }
          }
          scene.remove(p.mesh);if(p.mat)p.mat.dispose();if(p.mesh.geometry)p.mesh.geometry.dispose();
          PROJECTILES.list.splice(i,1);
          continue;
        }
      }
    }
    // Expire
    if(p.age>p.maxAge){
      if(p.fromPlayer){
        const ownerPl=(p.ownerSlot|0)===1?P2:P;
        const pFeel=_weaponCombatProfile(p.weaponIdx);
        if(ownerPl){
          ownerPl._gunplayMissBloom=Math.max(ownerPl._gunplayMissBloom||0,.24*(pFeel.missBloom||.30)/.30);
          ownerPl._gunplayConfidence=(ownerPl._gunplayConfidence||0)*.72;
          ownerPl._gunplayLastOutcome='miss';
          recordShotOutcomeFeedback(ownerPl,{hit:false,weaponIdx:p.weaponIdx,nowMs:performance.now()});
          recordGunplayOutcome(ownerPl,{hit:false,weaponIdx:p.weaponIdx,outcome:'miss',nowMs:performance.now()});
        }
      }
      scene.remove(p.mesh);if(p.mat)p.mat.dispose();if(p.mesh.geometry)p.mesh.geometry.dispose();
      PROJECTILES.list.splice(i,1);
    }
  }
}
// ── PER-WEAPON RECOIL PATTERNS — fixed deltas per consecutive shot.
