    if(pl.attachments.muzzle&&pl.attachments.muzzle.recoilMul)m*=pl.attachments.muzzle.recoilMul;
    if(pl.attachments.foregrip&&pl.attachments.foregrip.recoilMul)m*=pl.attachments.foregrip.recoilMul;
