    4:{pos:[0,-.080,-.030],dim:[.024,.080,.030]},
    5:{pos:[0,-.054,-.020],dim:[.030,.080,.040]},
    6:{pos:[0,-.105,.040],dim:[.036,.055,.050]},
    7:{pos:[0,-.034,-.020],dim:[.030,.060,.040]}
