  const enter=THREE.MathUtils.clamp(P._focusEnterPulse||0,0,1);
  const exit=THREE.MathUtils.clamp(P._focusExitPulse||0,0,1);
  const warn=THREE.MathUtils.clamp(P._focusWarnPulse||0,0,1);
