  const popMat=new THREE.MeshBasicMaterial({color:killed?0xfff4a8:0xffd7a0,transparent:true,opacity:.68,depthWrite:false,depthTest:true,blending:THREE.AdditiveBlending,side:THREE.DoubleSide});
