// ── DEEPER FOCUS MODE BEHAVIOR — special interactions
function _spawnFocusScreenShockwave(strength=1,color=0x72eaff){
  if(!camera||!scene)return;
  const am=typeof _additiveVfxTierMul==='function'?_additiveVfxTierMul():1;
  const fwd=new THREE.Vector3(0,0,-1).applyQuaternion(camera.quaternion);
  const right=new THREE.Vector3(1,0,0).applyQuaternion(camera.quaternion);
  const up=new THREE.Vector3(0,1,0).applyQuaternion(camera.quaternion);
  const center=camera.position.clone().addScaledVector(fwd,.92);
  const ringM=new THREE.MeshBasicMaterial({color,transparent:true,opacity:.72*strength*am,depthWrite:false,blending:THREE.AdditiveBlending,side:THREE.DoubleSide});
  const ring=new THREE.Mesh(new THREE.RingGeometry(.12,.46,48),ringM);
  ring.position.copy(center);
  ring.quaternion.copy(camera.quaternion);
  scene.add(ring);
  G.trails.push({mesh:ring,mat:ringM,timer:.24*strength,maxTime:.24*strength,isFocusShock:true,faceCameraBillboard:true});
  for(let i=0;i<5;i++){
    const side=(i-2)*.18+(Math.random()-.5)*.05;
    const high=(Math.random()-.5)*.16;
    const len=.34+Math.random()*.42;
    const streakM=new THREE.MeshBasicMaterial({color:i%2?0xffd060:color,transparent:true,opacity:.24*strength*am,depthWrite:false,blending:THREE.AdditiveBlending,side:THREE.DoubleSide});
    const streak=new THREE.Mesh(new THREE.PlaneGeometry(len,.010+Math.random()*.010),streakM);
    streak.position.copy(center).addScaledVector(right,side).addScaledVector(up,high).addScaledVector(fwd,Math.random()*.20);
    streak.quaternion.copy(camera.quaternion);
    streak.rotation.z+=(Math.random()-.5)*.22;
    scene.add(streak);
    G.trails.push({mesh:streak,mat:streakM,timer:.16+Math.random()*.08,maxTime:.20,isFlash:true,faceCameraBillboard:true});
  }
}
function _onFocusActivated(){
  _spawnFocusScreenShockwave(1,0x72eaff);
  sfxFocusOn();
  PP.shakeX+=(Math.random()-.5)*.18;
  PP.shakeY-=.10;
  P.dmgPitch-=.010;
  P._focusCameraKick=Math.max(P._focusCameraKick||0,1);
  _stabilizeFocusAdsViewmodelState('focus-enter');
}
function _onFocusEnded(reason='manual'){
  _spawnFocusScreenShockwave(reason==='empty'?.62:.48,reason==='empty'?0xffd060:0x9fe8ff);
  sfxFocusOff(reason==='empty');
  PP.shakeY+=reason==='empty'?.08:.04;
  _stabilizeFocusAdsViewmodelState(`focus-exit:${reason}`);
}
function _flashScreenColor(hex,duration){
  const f=document.createElement('div');
  f.style.cssText='position:fixed;inset:0;pointer-events:none;z-index:14;mix-blend-mode:screen;background:#'+hex.toString(16).padStart(6,'0')+';opacity:.55';
  document.body.appendChild(f);
  f.animate([{opacity:.55},{opacity:0}],{duration:duration||300,easing:'ease-out'}).onfinish=()=>f.remove();
}
// ── EXTENDED COMBAT KILL FEEDBACK — varied cinematic moments per kill type
function cinematicKillEnhanced(hitPt,enemy){
  // Standard kill cinematic
  cinematicKill(hitPt);
  // Type-specific extra
  if(enemy){
    if(enemy.isBoss){
      // Boss kill — extra intense
      _flashScreenColor(0xffd060,800);
      triggerKillCamSlowMo(.20,2.5);
    } else if(enemy.isLieutenant){
      // Lieutenant kill — medium cinematic
      _flashScreenColor(0xff5048,500);
      triggerKillCamSlowMo(.40,1.0);
    } else if(P.combo&&P.combo.count>=10){
      // Streak kill — quick flash
      _flashScreenColor(0xffd060,200);
    }
  }
}
// ── DETAILED STATS BREAKDOWN — for end-of-run summary
function generateRunSummary(){
  const elapsed=P.runStart?(performance.now()-P.runStart)/1000:0;
  const min=Math.floor(elapsed/60),sec=Math.floor(elapsed%60);
  const time=`${min<10?'0':''}${min}:${sec<10?'0':''}${sec}`;
  const acc=P.shotsFired>0?Math.round(P.shotsHit/P.shotsFired*100):0;
  const hsRate=P.kills>0?Math.round(P.headshots/P.kills*100):0;
  return {
    operator:G.operator||'echo',
    difficulty:G.difficulty||'normal',
    buildingsCleared:Math.max(0,G.building-1),
    totalKills:P.kills,
    headshots:P.headshots,
    headshotRate:hsRate,
    accuracy:acc,
    shotsFired:P.shotsFired,
    shotsHit:P.shotsHit,
    executions:P.execs||0,
    creditsEarned:P.money,
    timeStr:time,
    timeSec:elapsed,
    finalScore:P.score||0,
    grade:PROGRESS.bestGrade||'-',
    achievements:Object.keys(PROGRESS.achievements||{}).length,
    skinsUnlocked:Object.keys(PROGRESS).filter(k=>k.startsWith('_skin_')&&PROGRESS[k]).length,
    perksOwned:Object.keys(PROGRESS.perks||{}).filter(k=>PROGRESS.perks[k]).length,
    operatorLevel:PROGRESS.level
  };
}
// Track last damage time for recent-damage gates such as slide regen.
const _origTakeDamage=takeDamage;
takeDamage=function(amt,slot=0){
  const pl=slot===1?P2:P;
  pl._lastDamageTime=performance.now();
  return _origTakeDamage(amt,slot);
};
