const OBJECTIVE_DEFS={
  5: {kind:'stations',stations:[{x:-13,z:-16},{x:0,z:-18},{x:13,z:-15}],radius:2.0,dwellMs:500,total:3,
      labelFn:o=>'EXPOSE SURGERY RECORDS — '+(o.visited||0)+' / '+o.total},
  7: {kind:'stealth',label:'QUIET THE DECK — NO ALARM',
      labelFn:o=>o.alarmed?'ALARM RAISED — REINFORCEMENTS DOUBLED':'QUIET THE DECK — NO ALARM'},
  10:{kind:'timer',timerS:90,label:'REACH THE BELL TOWER',
      labelFn:o=>'BELL TOWER — '+Math.max(0,Math.ceil(o.remainingS||0))+'s'},
};
function _objectiveCloseEnemyCount(radius=9){
  if(!G.enemyMgr||!Array.isArray(G.enemyMgr._list)||!P.pos)return 0;
  const r2=radius*radius;
  let count=0;
  for(const e of G.enemyMgr._list){
    if(!e||e.dead||!e.group||!e.group.position)continue;
    const dx=e.group.position.x-P.pos.x,dz=e.group.position.z-P.pos.z;
    if(dx*dx+dz*dz<=r2)count++;
  }
  return count;
}
function _objectiveFeelContext(o,extra={}){
  const roomsCleared=Array.isArray(G.zoneClears)?G.zoneClears.filter(Boolean).length:0;
  return Object.assign({
    player:P,
    nowMs:performance.now(),
    enemiesAlive:G.enemyMgr?G.enemyMgr.aliveCount|0:0,
    closeEnemyCount:_objectiveCloseEnemyCount(9),
    roomsCleared,
    roomsTotal:3,
    exitUnlocked:!!G.exitUnlocked,
    alarmed:!!(G.levelState&&G.levelState.alarm),
  },extra||{});
}
function _updateStoryObjectiveActionRig(feel=null,dt=0,opts={}){
  const active=!!(feel&&feel.active);
  const hold=active?THREE.MathUtils.clamp(feel.holding?1:0,0,1):0;
  const near=active?THREE.MathUtils.clamp(feel.near?1:0,0,1):0;
  const urgency=active?THREE.MathUtils.clamp(feel.urgency||0,0,1):0;
  const affordance=active?THREE.MathUtils.clamp(feel.affordance||0,0,1):0;
  const progress=active?THREE.MathUtils.clamp(feel.progress||0,0,1):0;
  const contested=active?THREE.MathUtils.clamp(feel.contested||0,0,1):0;
  const holdStrain=active?THREE.MathUtils.clamp(feel.holdStrain||0,0,1):0;
  const interactionLead=active?THREE.MathUtils.clamp(feel.interactionLead||0,0,1):0;
  const completionAnticipation=active?THREE.MathUtils.clamp(feel.completionAnticipation||0,0,1):0;
  const failPressure=feel?THREE.MathUtils.clamp(feel.failPressure||0,0,1):0;
  const objectiveCadence=active?THREE.MathUtils.clamp(feel.objectiveCadence||0,0,1):0;
  const playerReachWeight=active?THREE.MathUtils.clamp(feel.playerReachWeight||0,0,1):0;
  const playerBraceWeight=active?THREE.MathUtils.clamp(feel.playerBraceWeight||0,0,1):0;
  const cameraTension=active?THREE.MathUtils.clamp(feel.cameraTension||0,0,1):0;
  const interact=THREE.MathUtils.clamp(P._objectiveInteractPulse||0,0,1);
  const complete=THREE.MathUtils.clamp(P._objectiveCompletePulse||0,0,1);
  const failed=feel&&feel.failed?1:0;
  const braceTarget=THREE.MathUtils.clamp(hold*(.38+urgency*.28+contested*.18)+playerBraceWeight*.46+holdStrain*.22+interact*.26+complete*.12,0,1.24);
  const reachTarget=THREE.MathUtils.clamp(near*affordance*.32+hold*.38+playerReachWeight*.56+interactionLead*.34+interact*.55+complete*.16,0,1.26);
  const pressureTarget=THREE.MathUtils.clamp(urgency*.46+contested*.28+cameraTension*.34+failPressure*.54+failed*.55,0,1.22);
  const stabilizeTarget=THREE.MathUtils.clamp(completionAnticipation*.46+objectiveCadence*.22+complete*.52-urgency*.12-failPressure*.18,0,1.10);
  const promptTarget=THREE.MathUtils.clamp(interactionLead*.54+near*affordance*.16+Math.sin(performance.now()*.0065)*.04,0,1.08);
  const payoffTarget=THREE.MathUtils.clamp(completionAnticipation*.72+complete*.44,0,1.18);
  const failTarget=THREE.MathUtils.clamp(failPressure*.76+failed*.42,0,1.18);
  const progressBeat=active?(Math.sin(progress*Math.PI)*hold+objectiveCadence*.28+completionAnticipation*.18):0;
  P._objectiveBracePulse=damp(Number.isFinite(P._objectiveBracePulse)?P._objectiveBracePulse:0,braceTarget,braceTarget>.05?7.2:6.4,dt);
  P._objectiveReachPulse=damp(Number.isFinite(P._objectiveReachPulse)?P._objectiveReachPulse:0,reachTarget,reachTarget>.05?8.4:7.0,dt);
  P._objectivePressurePulse=damp(Number.isFinite(P._objectivePressurePulse)?P._objectivePressurePulse:0,pressureTarget,pressureTarget>.05?6.4:7.6,dt);
  P._objectiveProgressBeat=damp(Number.isFinite(P._objectiveProgressBeat)?P._objectiveProgressBeat:0,progressBeat,progressBeat>.05?7.8:6.2,dt);
  P._objectiveStabilizePulse=damp(Number.isFinite(P._objectiveStabilizePulse)?P._objectiveStabilizePulse:0,stabilizeTarget,stabilizeTarget>.05?6.6:7.8,dt);
  P._objectivePromptPulse=damp(Number.isFinite(P._objectivePromptPulse)?P._objectivePromptPulse:0,promptTarget,promptTarget>.05?8.8:8.0,dt);
  P._objectivePayoffAnticipationPulse=damp(Number.isFinite(P._objectivePayoffAnticipationPulse)?P._objectivePayoffAnticipationPulse:0,payoffTarget,payoffTarget>.05?6.8:6.0,dt);
  P._objectiveFailPressurePulse=damp(Number.isFinite(P._objectiveFailPressurePulse)?P._objectiveFailPressurePulse:0,failTarget,failTarget>.05?7.0:7.4,dt);
  P._objectiveCompletePulse=damp(Number.isFinite(P._objectiveCompletePulse)?P._objectiveCompletePulse:0,0,5.0,dt);
  P._storyObjectiveActionRig={
    version:'story-objective-action-rig.v2',
    active,
    label:feel&&feel.label||'none',
    kind:feel&&feel.kind||'none',
    source:(opts&&opts.source)||'objective',
    hold:Number(hold.toFixed(3)),
    reach:Number((P._objectiveReachPulse||0).toFixed(3)),
    brace:Number((P._objectiveBracePulse||0).toFixed(3)),
    pressure:Number((P._objectivePressurePulse||0).toFixed(3)),
    stabilize:Number((P._objectiveStabilizePulse||0).toFixed(3)),
    prompt:Number((P._objectivePromptPulse||0).toFixed(3)),
    anticipation:Number((P._objectivePayoffAnticipationPulse||0).toFixed(3)),
    fail:Number((P._objectiveFailPressurePulse||0).toFixed(3)),
    progress:Number(progress.toFixed(3)),
    progressBeat:Number((P._objectiveProgressBeat||0).toFixed(3)),
    urgency:Number(urgency.toFixed(3)),
    holdStrain:Number(holdStrain.toFixed(3)),
    interactionLead:Number(interactionLead.toFixed(3)),
    objectiveCadence:Number(objectiveCadence.toFixed(3)),
    interact:Number(interact.toFixed(3)),
    complete:Number(complete.toFixed(3))
  };
  return P._storyObjectiveActionRig;
}
function applyStoryObjectivePayoff(kind='complete',opts={}){
  const storyMode=!!(G&&G.campaignLevel&&G.playMode!=='duel');
  const inactive={version:'story-objective-payoff.v1',active:false,count:0};
  if(!storyMode||!P||P.dead)return inactive;
  const nowMs=performance.now();
  const k=String(kind||'complete');
  const stationStep=k==='station-step';
  const relay=k==='alarm-disabled'||k==='relay-hack';
  const strength=THREE.MathUtils.clamp(Number.isFinite(opts&&opts.strength)?opts.strength:(stationStep?.55:(relay?1.05:1.0)),0,1.22);
  const side=Number.isFinite(opts&&opts.side)?opts.side:(((P.combo&&P.combo.count)||0)%2?1:-1);
  P._storyObjectivePayoffPulse=Math.max(P._storyObjectivePayoffPulse||0,strength);
  P._storyObjectivePayoffSide=side;
  P._objectiveCompletePulse=Math.max(P._objectiveCompletePulse||0,stationStep?.36:.92);
  P._storyAimChainPulse=Math.max(P._storyAimChainPulse||0,stationStep?.22:.48);
  P._reloadReadyPulse=Math.max(P._reloadReadyPulse||0,stationStep?.24:.62);
  P._weaponHandlingReady=Math.max(P._weaponHandlingReady||0,stationStep?.30:.72);
  P._combatFlow=Math.max(P._combatFlow||0,stationStep?.34:.78);
  P._combatFlowUntil=Math.max(P._combatFlowUntil||0,nowMs+(stationStep?420:780));
  if(!stationStep&&(P.focus||0)<1)P.focus=Math.min(1,(P.focus||0)+(relay?.065:.045));
  const affected=[];
  if(G.enemyMgr&&Array.isArray(G.enemyMgr._list)){
    const radius=relay?14:10;
    for(const e of G.enemyMgr._list){
      if(!e||e.dead||!e.group||!e.group.position)continue;
      const ep=e.group.position;
      const dx=ep.x-P.pos.x,dz=ep.z-P.pos.z;
      const dist=Math.sqrt(dx*dx+dz*dz);
      if(dist>radius)continue;
      const fall=THREE.MathUtils.clamp(1-dist/radius,0,1);
      const power=THREE.MathUtils.clamp((stationStep?.20:.34)+fall*(stationStep?.35:.66),0,1.05)*strength;
      e._storyObjectivePayoffEnemyPulse=Math.max(e._storyObjectivePayoffEnemyPulse||0,power);
      e._storyObjectivePayoffEnemySide=Math.sign(dx)||side;
      e._storyReadabilityPulse=Math.max(e._storyReadabilityPulse||0,Math.min(1,power*.66+.08));
      e.aimReady=Math.max(0,(e.aimReady||0)-power*.16);
      e.shootTimer=Math.max(e.shootTimer||0,.08+power*.24);
      e.burstCooldown=Math.max(e.burstCooldown||0,.08+power*.20);
      if(relay)e._suppressedUntil=Math.max(e._suppressedUntil||0,nowMs+260+power*260);
      if(e.group.userData)e.group.userData.storyObjectivePayoff={version:'story-objective-payoff.v1',kind:k,power:Number(power.toFixed(3)),dist:Number(dist.toFixed(2))};
      affected.push({type:e.type||'enemy',power:Number(power.toFixed(3)),dist:Number(dist.toFixed(2))});
    }
  }
  const snap={version:'story-objective-payoff.v1',active:true,kind:k,strength:Number(strength.toFixed(3)),side,count:affected.length,affected:affected.slice(0,10)};
  P._lastStoryObjectivePayoff=snap;
  G._lastStoryObjectivePayoff=snap;
  return snap;
}
function applyStoryObjectiveLivePressure(feel=null,opts={}){
  const storyMode=!!(G&&G.campaignLevel&&G.playMode!=='duel');
  if(!storyMode||!feel||!feel.active||!P||P.dead||!G.enemyMgr||!Array.isArray(G.enemyMgr._list))return null;
  const holdStrain=THREE.MathUtils.clamp(feel.holdStrain||0,0,1);
  const cameraTension=THREE.MathUtils.clamp(feel.cameraTension||0,0,1);
  const anticipation=THREE.MathUtils.clamp(feel.completionAnticipation||0,0,1);
  const cadence=THREE.MathUtils.clamp(feel.objectiveCadence||0,0,1);
  const failPressure=THREE.MathUtils.clamp(feel.failPressure||0,0,1);
  const telegraphMul=THREE.MathUtils.clamp(feel.enemyTelegraphMul||1,.82,1.32);
  const base=THREE.MathUtils.clamp(holdStrain*.42+cameraTension*.30+anticipation*.28+cadence*.22+failPressure*.18,0,1.22);
  if(base<.045)return null;
  const nowMs=performance.now();
  const radius=THREE.MathUtils.clamp((opts.radius||8.5)+cameraTension*4.0+anticipation*2.0,6,15);
  const affected=[];
  for(const e of G.enemyMgr._list){
    if(!e||e.dead||!e.group||!e.group.position)continue;
    const ep=e.group.position;
    const dx=ep.x-P.pos.x,dz=ep.z-P.pos.z;
    const dist=Math.sqrt(dx*dx+dz*dz);
    if(dist>radius)continue;
    const fall=THREE.MathUtils.clamp(1-dist/radius,0,1);
    const power=THREE.MathUtils.clamp((.16+fall*.84)*base,0,1.10);
    if(power<.035)continue;
    e._storyObjectiveTensionPulse=Math.max(e._storyObjectiveTensionPulse||0,power);
    e._storyObjectiveTensionSide=Math.sign(dx)||((Math.sin(nowMs*.003+dist)>0)?1:-1);
    e._storyReadabilityPulse=Math.max(e._storyReadabilityPulse||0,Math.min(1,power*.40+cadence*.18));
    e._fpHoldBoost=Math.max(e._fpHoldBoost||0,power*.08+anticipation*.035);
    e.shootTimer=Math.max(e.shootTimer||0,.035+power*.045*telegraphMul);
    e.burstCooldown=Math.max(e.burstCooldown||0,.025+power*.035*telegraphMul);
    if(e.group.userData)e.group.userData.storyObjectiveLivePressure={version:'story-objective-live-pressure.v1',power:Number(power.toFixed(3)),dist:Number(dist.toFixed(2)),label:feel.label||'objective'};
    affected.push({type:e.type||'enemy',power:Number(power.toFixed(3)),dist:Number(dist.toFixed(2))});
  }
  const snap={version:'story-objective-live-pressure.v1',active:affected.length>0,label:feel.label||'objective',kind:feel.kind||'objective',base:Number(base.toFixed(3)),count:affected.length,affected:affected.slice(0,10)};
  P._lastStoryObjectiveLivePressure=snap;
  G._lastStoryObjectiveLivePressure=snap;
  return snap;
}
function _refreshObjectiveHud(o){
  const el=document.getElementById('objective-ticker');
  if(!el||!o||!o.def)return;
  const label=document.getElementById('objective-ticker-label');
  const fill=document.getElementById('objective-ticker-fill');
  const txt='▣ '+(o.def.labelFn?o.def.labelFn(o):o.def.label);
  if(label){
    if(label._lastTxt!==txt){label.textContent=txt;label._lastTxt=txt;}
  }else if(el._lastTxt!==txt){el.textContent=txt;el._lastTxt=txt;}
  const feel=o.feel||buildStoryObjectiveFeelSnapshot(o,_objectiveFeelContext(o));
  if(fill){
    const progress=THREE.MathUtils.clamp(feel.progress||0,0,1);
    fill.style.width=(progress*100).toFixed(1)+'%';
    const color=feel.failed?'#ff5040':feel.completed?'#5fcb52':feel.holding?'#40ffc8':feel.urgency>.5?'#ffb060':'#ffd060';
    fill.style.background=`linear-gradient(90deg,${color},rgba(255,255,255,.80))`;
    fill.style.boxShadow=`0 0 ${Math.round(4+(feel.objectiveCadence||0)*16)}px ${color}`;
  }
  el.dataset.kind=feel.kind||'objective';
  el.dataset.label=feel.label||'objective';
  el.dataset.feelVersion=STORY_OBJECTIVE_FEEL_VERSION;
  el.style.transform=`translateY(${((feel.cameraTension||0)*-1.5+(feel.completionAnticipation||0)*1.2).toFixed(2)}px)`;
  el.style.boxShadow=`0 2px ${Math.round(12+(feel.objectiveCadence||0)*14)}px rgba(0,0,0,.45),0 0 ${Math.round((feel.completionAnticipation||0)*14)}px rgba(95,203,82,.22)`;
}
function _initObjectiveForBuilding(bn){
  // Always tear down previous HUD element
  const prior=document.getElementById('objective-ticker');
  if(prior&&prior.parentNode)prior.parentNode.removeChild(prior);
  // Also drop the shotgun-pellets HUD between buildings so it doesn't leak
  // across runs that ended in ADS pose.
  const sg=document.getElementById('sg-pellets');
  if(sg)sg.style.opacity='0';
  G._objective=null;
  const def=OBJECTIVE_DEFS[bn];
  if(!def)return;
  // Construct runtime state
  G._objective={
    bn, def, kind:def.kind,
    total:def.total||1,
    visited: def.kind==='stations'?0:undefined,
    visitedFlags: def.kind==='stations'?new Array(def.total).fill(false):undefined,
    dwellStart: null,
    _dwellIdx:-1,
    _stationHoldProgress:0,
    _nearestStationDist:999,
    _nearStationIdx:-1,
    alarmed: def.kind==='stealth'?false:undefined,
    remainingS: def.kind==='timer'?def.timerS:undefined,
    completed:false,
    failed:false,
    feel:null,
  };
  // Build HUD element
  const el=document.createElement('div');
  el.id='objective-ticker';
  el.style.cssText='position:fixed;left:14px;top:14px;z-index:30;font:700 13px Rajdhani,sans-serif;color:#ffd060;letter-spacing:.16em;background:rgba(8,10,14,.76);padding:8px 14px 10px;border-left:3px solid #ffd060;box-shadow:0 2px 12px rgba(0,0,0,.45);pointer-events:none;min-width:230px';
  const label=document.createElement('div');
  label.id='objective-ticker-label';
  label.textContent='▣ '+(def.labelFn?def.labelFn(G._objective):def.label);
  const bar=document.createElement('div');
  bar.id='objective-ticker-bar';
  bar.style.cssText='height:3px;margin-top:7px;background:rgba(255,255,255,.11);overflow:hidden';
  const fill=document.createElement('div');
  fill.id='objective-ticker-fill';
  fill.style.cssText='height:100%;width:0%;background:linear-gradient(90deg,#ffd060,rgba(255,255,255,.80));transition:width .10s linear';
  bar.appendChild(fill);
  el.append(label,bar);
  document.body.appendChild(el);
  G._objective.feel=buildStoryObjectiveFeelSnapshot(G._objective,_objectiveFeelContext(G._objective));
  _refreshObjectiveHud(G._objective);
}
function tickObjective(dt){
  const o=G._objective;
  if(!o||!o.def)return;
  const def=o.def;
  const nowMs=performance.now();
  const ctxBase=_objectiveFeelContext(o);
  let feelExtra={};
  if(!o.completed&&!o.failed&&def.kind==='stations'){
    let matched=false,nearestDist=999,nearestIdx=-1;
    const closeCount=ctxBase.closeEnemyCount||0;
    const holdMs=(def.dwellMs||500)*(1+Math.min(.30,closeCount*.055));
    for(let i=0;i<def.stations.length;i++){
      const st=def.stations[i];
      const dx=P.pos.x-st.x,dz=P.pos.z-st.z;
      const d=Math.sqrt(dx*dx+dz*dz);
      if(d<nearestDist){nearestDist=d;nearestIdx=i;}
      if(o.visitedFlags[i])continue;
      if(d<def.radius){
        matched=true;
        if(o.dwellStart==null||o._dwellIdx!==i){o.dwellStart=nowMs;o._dwellIdx=i;o._stationHoldProgress=0;}
        o._stationHoldProgress=THREE.MathUtils.clamp((nowMs-o.dwellStart)/Math.max(1,holdMs),0,1);
        if(o._stationHoldProgress>=1){
          o.visitedFlags[i]=true;
          o.visited=(o.visited||0)+1;
          o.dwellStart=null;
          o._stationHoldProgress=0;
	          o._lastObjectivePulseAt=nowMs;
	          P._objectiveInteractPulse=Math.max(P._objectiveInteractPulse||0,.86);
	          if(typeof attachToast==='function')attachToast('<div style="color:#ffd060;letter-spacing:.20em">▣ CHART '+o.visited+' / '+o.total+'</div>',1400);
	          if(o.visited>=o.total)o.completed=true;
	          else if(typeof applyStoryObjectivePayoff==='function')applyStoryObjectivePayoff('station-step',{strength:.58,side:i%2?1:-1});
        }
        break;
      }
    }
    if(!matched){
      o.dwellStart=null;
      o._dwellIdx=-1;
      o._stationHoldProgress=Math.max(0,(o._stationHoldProgress||0)-dt*2.6);
    }
    o._nearestStationDist=nearestDist;
    o._nearStationIdx=nearestIdx;
    feelExtra={near:matched||nearestDist<def.radius,dwellProgress:o._stationHoldProgress||0,holding:matched,nearestDistance:nearestDist,radius:def.radius};
  } else if(!o.completed&&!o.failed&&def.kind==='stealth'){
    // If any non-dead enemy currently has LOS to the player, alarm.
    if(!o.alarmed&&G.enemyMgr){
      for(const e of G.enemyMgr._list){
        if(e.dead)continue;
        if(e.state===ATTACK||e.state===CHASE){
          if(e.canSee(P.pos,G.levelData.walls||[])){
            o.alarmed=true;
	            o.alarmRaisedAt=nowMs;
	            // Only fail mastery if THIS building's mastery is genuinely the no-alarm/stealth condition.
	            // The stealth objective is also authored for buildings (e.g. B07 no-heal) whose mastery is
	            // unrelated to alarms, so we must not blanket-fail mastery on any alarm. (decoupled)
	            if(G.mastery&&/no_alarm|alarm|stealth|silent/i.test(String(G.mastery.objective&&G.mastery.objective.id||''))){G.mastery.failed=true;G.levelState&&(G.levelState.masteryFailed=true);}
	            if(typeof attachToast==='function')attachToast('<div style="color:#ff5040;letter-spacing:.20em">ALARM RAISED</div>',2200);
	            if(typeof applyStoryAlarmRaisedCinematic==='function')applyStoryAlarmRaisedCinematic(e,{source:'stealth-objective',strength:1});
	            if(G.enemyMgr){
              const peers=G.enemyMgr._list.filter(x=>x&&!x.dead&&x.group&&x.group.position).map(x=>({x:x.group.position.x,z:x.group.position.z}));
              const walls=G.levelData&&G.levelData.walls||[];
              for(let k=0;k<2;k++){
                const ang=Math.random()*Math.PI*2,dist=5.5+Math.random()*3.5;
                const want=new THREE.Vector3(P.pos.x+Math.cos(ang)*dist,WT,P.pos.z+Math.sin(ang)*dist);
                const opts={zoneId:typeof playerZone==='function'?playerZone():1,peerR:_enemySpawnPeerRadius('soldier'),requireNav:true,strictZone:false};
                let pos=null;
                try{pos=typeof _findClearEnemySpawn==='function'?_findClearEnemySpawn(want,walls,.46,peers,opts):null;}catch(_){pos=null;}
                if(!pos)pos=want;
                peers.push({x:pos.x,z:pos.z});
	                const e2=new Enemy(scene,pos,G.building||1,'soldier');
	                e2.zoneId=opts.zoneId;e2.state=ALERT;e2.alertTimer=.85;e2.lastKnownPos=new THREE.Vector3(P.pos.x,0,P.pos.z);
	                e2._storyAlarmWakePulse=Math.max(e2._storyAlarmWakePulse||0,.92);
	                e2._storyAlarmWakeSide=Math.random()<.5?-1:1;
	                if(e2.group&&e2.group.userData)e2.group.userData.storyAlarmWake={version:'story-alarm-cinematic.v1',spawned:true,power:.92,dormant:false};
	                G.enemyMgr._list.push(e2);_flagSsrSolidsDirty();
              }
            }
            break;
          }
        }
      }
    }
    if(G.exitUnlocked&&!o.alarmed)o.completed=true;
    feelExtra={alarmed:o.alarmed,holding:false,roomsCleared:Array.isArray(G.zoneClears)?G.zoneClears.filter(Boolean).length:0,roomsTotal:3,exitUnlocked:!!G.exitUnlocked};
  } else if(!o.completed&&!o.failed&&def.kind==='timer'){
    const reachedBack=typeof playerZone==='function'&&playerZone()===2;
    if(reachedBack||G.exitUnlocked||(Array.isArray(G.zoneClears)&&G.zoneClears[1])){
      o.completed=true;
    }else{
      o.remainingS=Math.max(0,o.remainingS-dt);
      if(o.remainingS<=0&&!o.completed){
        o.failed=true;
        // Only fail mastery if THIS building's mastery is genuinely a "reach in time" condition.
        // The timer objective is authored for buildings (e.g. B10 silent-choir) whose mastery is
        // unrelated to a countdown, so we must not blanket-fail mastery on timeout. (decoupled)
        if(G.mastery&&/no_helo|no_engine_alarm|fastline|intact|grounded|cold_engines|timer|time/i.test(String(G.mastery.objective&&G.mastery.objective.id||''))){G.mastery.failed=true;G.levelState&&(G.levelState.masteryFailed=true);}
        if(typeof attachToast==='function')attachToast('<div style="color:#ff5040;letter-spacing:.20em">BELL TOWER TIMED OUT</div>',2200);
      }
    }
    feelExtra={timerS:def.timerS,remainingS:o.remainingS,holding:false};
  }
  o.feel=buildStoryObjectiveFeelSnapshot(o,_objectiveFeelContext(o,feelExtra));
  G._storyObjectiveFeel=o.feel;
  P._storyObjectiveFeel=o.feel;
  P._objectiveProgress=o.feel.progress||0;
  P._objectiveHoldPulse=damp(Number.isFinite(P._objectiveHoldPulse)?P._objectiveHoldPulse:0,o.feel.holding?1:0,8.0,dt);
  P._objectiveUrgencyPulse=damp(Number.isFinite(P._objectiveUrgencyPulse)?P._objectiveUrgencyPulse:0,o.feel.urgency||0,6.2,dt);
  P._objectiveInteractPulse=damp(Number.isFinite(P._objectiveInteractPulse)?P._objectiveInteractPulse:0,0,5.8,dt);
  _updateStoryObjectiveActionRig(o.feel,dt,{source:'building-objective'});
  if(typeof applyStoryObjectiveLivePressure==='function')applyStoryObjectiveLivePressure(o.feel,{source:'building-objective'});
  if(o.feel.holding||o.feel.urgency>.15){
    const _objCad=THREE.MathUtils.clamp(o.feel.objectiveCadence||0,0,1);
    const _objAnt=THREE.MathUtils.clamp(o.feel.completionAnticipation||0,0,1);
    P._combatFlow=Math.max(P._combatFlow||0,Math.min(.88,(o.feel.affordance||0)*.20+(o.feel.urgency||0)*.16+_objCad*.14+_objAnt*.10));
    P._weaponHandlingUrgency=Math.max(P._weaponHandlingUrgency||0,Math.min(.70,(o.feel.urgency||0)*.28+(o.feel.holding ? .16 : 0)+_objCad*.14));
    P._storyThreatReadPulse=Math.max(P._storyThreatReadPulse||0,Math.min(.46,(o.feel.cameraTension||0)*.22+_objCad*.16));
    if(_objAnt>.18)P._storyRecoveryBreatherPulse=Math.max(P._storyRecoveryBreatherPulse||0,Math.min(.38,_objAnt*.22));
  }
  // Phase AF: on completion, banner + dismiss HUD after fade. Objective
  // success cues mastery success on the appropriate buildings.
	  if(o.completed&&!o._announced){
	    o._announced=true;
	    P._objectiveCompletePulse=Math.max(P._objectiveCompletePulse||0,1);
	    if(typeof applyStoryObjectivePayoff==='function')applyStoryObjectivePayoff('complete',{strength:1});
	    _updateStoryObjectiveActionRig(o.feel,dt,{source:'objective-complete'});
    if(typeof attachToast==='function')attachToast('<div style="color:#5fcb52;letter-spacing:.20em;font-weight:900">✓ OBJECTIVE COMPLETE</div>',2200);
    const el2=document.getElementById('objective-ticker');
    if(el2){el2.style.borderLeftColor='#5fcb52';el2.style.color='#5fcb52';
      setTimeout(()=>{el2.style.transition='opacity .8s';el2.style.opacity='0';
        setTimeout(()=>{if(el2.parentNode)el2.parentNode.removeChild(el2);},900);},1800);}
  }
  if(o.failed&&!o._failedAnnounced){
    o._failedAnnounced=true;
    P._objectiveUrgencyPulse=Math.max(P._objectiveUrgencyPulse||0,1);
    const el2=document.getElementById('objective-ticker');
    if(el2){el2.style.borderLeftColor='#ff5040';el2.style.color='#ff8060';}
  }
  _refreshObjectiveHud(o);
}

function startInteractiveTutorial(){
  if(PROGRESS._tutorialSeen)return;
  G._tutState={ idx:0, fadeIn:0, fadeOut:0, doneAt:0, started:performance.now(), elementId:'tutorial-prompt' };
  // Build the DOM once
  let el=document.getElementById(G._tutState.elementId);
  if(!el){
    el=document.createElement('div');
    el.id=G._tutState.elementId;
    el.style.cssText='position:fixed;left:50%;top:18%;transform:translateX(-50%);z-index:42;font:600 16px Rajdhani,sans-serif;color:#ffd060;letter-spacing:.18em;background:rgba(8,10,14,.75);padding:10px 18px;border:1px solid rgba(255,200,80,.45);box-shadow:0 4px 22px rgba(255,180,40,.15);opacity:0;pointer-events:none;transition:opacity .35s';
    document.body.appendChild(el);
  }
}
function tickTutorial(dt){
  const s=G._tutState;
  if(!s)return;
  const step=TUTORIAL_STEPS[s.idx];
  const el=document.getElementById(s.elementId);
  if(!step||!el){
    // Done — fade out + persist
    if(el){el.style.opacity='0';setTimeout(()=>{if(el.parentNode)el.parentNode.removeChild(el);},500);}
    PROGRESS._tutorialSeen=true;
    if(typeof saveProgressFile==='function')saveProgressFile();
    G._tutState=null;
    return;
  }
  // Update text and ensure visible
  if(el.dataset.id!==step.id){
    el.dataset.id=step.id;
    el.innerHTML=step.text;
    el.style.opacity='1';
  }
  // Track simple input events
  if(K&&(K['KeyW']||K['KeyA']||K['KeyS']||K['KeyD']))P._tutMoved=true;
  if(M&&(M.dx||M.dy))P._tutLooked=true;
  if(K&&K['KeyR'])P._tutReloaded=true;
  if(P.vaulting)P._tutVaulted=true;
  // Hook fire from shoot() via a flag set there
  // Check condition
  if(step.check()){
    el.style.opacity='0';
    s.idx++;
    setTimeout(()=>{ if(el)el.style.opacity='1'; }, 700);
  }
}

// ── DROPPED WEAPONS — fallen enemy weapons remain on floor, visual flavor
function spawnDroppedWeapon(pos,enemyType){
  const dropM=new THREE.MeshPhongMaterial({color:0x14141a,shininess:80,specular:0x303040});
  const grp=new THREE.Group();
  // Generic small weapon shape — 1 box approximating the enemy's gun
  const sizes={
    soldier:[.05,.05,.30],
    heavy:[.07,.07,.40],
    sniper:[.05,.05,.45],
    scout:[.05,.05,.20],
    pistolero:[.04,.04,.12],
    shielded:[.05,.05,.13],
    riot:[.05,.05,.16],
    demolitions:[.05,.05,.30],
    drone:[.04,.04,.10],
    marksman:[.05,.05,.40],
    lieutenant:[.05,.05,.20]
  };
  const sz=sizes[enemyType]||sizes.soldier;
  const wm=new THREE.Mesh(new THREE.BoxGeometry(sz[0],sz[1],sz[2]),dropM);
  grp.add(wm);
  // Magazine
  const mag=new THREE.Mesh(new THREE.BoxGeometry(.04,.10,.05),new THREE.MeshLambertMaterial({color:0x080808}));
  mag.position.set(0,-.06,sz[2]*-.10);grp.add(mag);
  // Position on floor with random orientation
  grp.position.copy(pos);
  grp.position.y=WT+.10;
  grp.rotation.set(Math.random()*Math.PI,Math.random()*Math.PI*2,Math.random()*Math.PI);
  scene.add(grp);
  // Persistent decoration — keep until level cleanup
  G.droppedWeapons=G.droppedWeapons||[];
  G.droppedWeapons.push(grp);
}
// ── PER-BUILDING SCORE MULTIPLIER — late buildings worth more
function buildingScoreMul(){
  const bn=G.building||1;
  return ({1:1.0,2:1.1,3:1.2,4:1.3,5:1.4,6:1.5,7:1.6,8:1.8})[bn]||1.0;
}
