      affected.push({type:e.type||'enemy',roomId:e.roomId||null,zoneId:Number.isFinite(e.zoneId)?e.zoneId:null,power:Number(power.toFixed(3)),dist:Number(dist.toFixed(2)),dormant:!!e._roomFlowDormant});
