  const spawnX=Number.isFinite(levelPlayerSpawn&&levelPlayerSpawn.x)?levelPlayerSpawn.x:0;
  const spawnZ=Number.isFinite(levelPlayerSpawn&&levelPlayerSpawn.z)?levelPlayerSpawn.z:18;
