// ── PER-RUN SAVE STATE (resume) ──────────────────────────────────────
function saveRunState(){
  if(!G.started||P.dead)return;
  if(G.playMode!=='solo'&&G.playMode!=='custom')return;
  normalizePlayerRuntime();
	  PROGRESS.runSave={
	    mode:G.playMode||'solo',
	    building:G.building,
	    packId:(G.playMode==='custom'||G.playMode==='editor-test')&&CUSTOM_MAP_RUNTIME.pack?CUSTOM_MAP_RUNTIME.pack.id:null,
	    mapId:(G.playMode==='custom'||G.playMode==='editor-test')&&CUSTOM_MAP_RUNTIME.map?CUSTOM_MAP_RUNTIME.map.id:null,
	    mapIndex:(G.playMode==='custom'||G.playMode==='editor-test')?CUSTOM_MAP_RUNTIME.mapIndex:0,
	    money:P.money,hp:P.hp,
    healPacks:P.healPacks,grenades:P.grenades,smokes:P.smokes,flashes:P.flashes,
    weaponIdx:P.weaponIdx,weaponAmmo:P.weaponAmmo.slice(0,WEAPONS.length),weaponRes:P.weaponRes.slice(0,WEAPONS.length),
    attachments:P.attachments?{
      scope:P.attachments.scope?{...P.attachments.scope}:null,
      mag:P.attachments.mag?{...P.attachments.mag}:null,
      muzzle:P.attachments.muzzle?{...P.attachments.muzzle}:null,
      foregrip:P.attachments.foregrip?{...P.attachments.foregrip}:null
    }:null,
    difficulty:G.difficulty||'normal',
    kills:P.kills,headshots:P.headshots,shotsFired:P.shotsFired,shotsHit:P.shotsHit,
    runStart:P.runStart,timestamp:Date.now()
  };
  saveProgressFile();
}
function clearRunState(){PROGRESS.runSave=null;saveProgressFile();}
function resumeRunState(){
  const r=PROGRESS.runSave;if(!r)return false;
  if(r.mode==='custom'){
    G._resumeState={hp:r.hp,weaponIdx:normalizeWeaponIdx(r.weaponIdx||START_WEAPON_IDX),weaponAmmo:Array.isArray(r.weaponAmmo)?r.weaponAmmo.slice(0,WEAPONS.length):null,weaponRes:Array.isArray(r.weaponRes)?r.weaponRes.slice(0,WEAPONS.length):null};
	    P.money=r.money||0;P.healPacks=r.healPacks||0;P.grenades=r.grenades||0;P.smokes=r.smokes||0;P.flashes=r.flashes||0;
	    P.attachments=_normalizeAttachments(r.attachments);G.difficulty=r.difficulty||'normal';
	    P.kills=r.kills||0;P.headshots=r.headshots||0;P.shotsFired=r.shotsFired||0;P.shotsHit=r.shotsHit||0;P.runStart=r.runStart||performance.now();
	    G._resumeCustomStats={money:P.money,healPacks:P.healPacks,grenades:P.grenades,smokes:P.smokes,flashes:P.flashes,kills:P.kills,headshots:P.headshots,shotsFired:P.shotsFired,shotsHit:P.shotsHit,runStart:P.runStart};
    startCustomMapPack(r.packId,r.mapIndex||0).catch(err=>{console.error('[custom-map] resume failed',err);clearRunState();quitToMain();});
    return true;
  }
  G.building=r.building;P.money=r.money;
  P.healPacks=r.healPacks||0;P.grenades=r.grenades||0;P.smokes=r.smokes||0;P.flashes=r.flashes||0;
  P.attachments=_normalizeAttachments(r.attachments);
  P.weaponIdx=normalizeWeaponIdx(r.weaponIdx||START_WEAPON_IDX);
  if(Array.isArray(r.weaponAmmo))P.weaponAmmo=r.weaponAmmo.slice(0,WEAPONS.length);
  if(Array.isArray(r.weaponRes))P.weaponRes=r.weaponRes.slice(0,WEAPONS.length);
  normalizePlayerRuntime();
  G._resumeState={hp:r.hp,weaponIdx:P.weaponIdx,weaponAmmo:P.weaponAmmo.slice(),weaponRes:P.weaponRes.slice()};
  G.difficulty=r.difficulty||'normal';
  P.kills=r.kills||0;P.headshots=r.headshots||0;
  P.shotsFired=r.shotsFired||0;P.shotsHit=r.shotsHit||0;
  P.runStart=r.runStart||performance.now();
  G.started=true;gameFocused=true;
  $e('overlay').classList.add('hidden');hideEndScreen();
  applyUnlocks();
  tryLock();musicInit();showBriefingCard(G.building,1800);startBuilding();
  return true;
}
// Local leaderboard — top 5 scoring runs
function saveLeaderboard(score,grade,kills,headshots,acc,timeStr,diff){
  PROGRESS.leaderboard=PROGRESS.leaderboard||[];
  PROGRESS.leaderboard.push({score,grade,kills,headshots,acc,time:timeStr,diff,date:new Date().toISOString().slice(0,10)});
  PROGRESS.leaderboard.sort((a,b)=>b.score-a.score);
  PROGRESS.leaderboard=PROGRESS.leaderboard.slice(0,5);
  saveProgressFile();
}
function saveProgress(score,grade){
  PROGRESS.runs+=1;
  if(grade!=='-')PROGRESS.wins+=1;
  if(score>PROGRESS.bestScore){PROGRESS.bestScore=score;PROGRESS.bestGrade=grade;}
  _accumulateStats();
  // XP scaled by score
  let gainXp=Math.round(score/12);
  // Daily challenge bonus
  const dc=dailyChallenge();
  if(!PROGRESS.daily.done){
    try{if(dc.check()){PROGRESS.daily.done=true;gainXp+=dc.bonus;
      attachToast(`<div style="color:#5fcb52;letter-spacing:.30em">✓ DAILY COMPLETE</div><div style="font-size:12px;margin-top:4px">+${dc.bonus} bonus XP</div>`,3500);
    }}catch(_){}
  }
  const oldLvl=PROGRESS.level;
  PROGRESS.xp+=gainXp;
  // Level curve: lvl N requires 800*N XP cumulative
  while(PROGRESS.xp>=PROGRESS.level*800){PROGRESS.level+=1;PROGRESS.perkPoints=(PROGRESS.perkPoints||0)+1;}
  // Unlock by level
  if(PROGRESS.level>=2)PROGRESS.unlocks.startCredits=true;
  if(PROGRESS.level>=3)PROGRESS.unlocks.startHeal=true;
  if(PROGRESS.level>=4)PROGRESS.unlocks.startGrenade=true;
  if(PROGRESS.level>=5)PROGRESS.unlocks.extraFocus=true;
  // Run cleared — wipe save state (run is over)
  if(grade==='-'||grade){clearRunState();}
  checkAchievements();
  saveProgressFile();
  // Toast for unlocks
  if(PROGRESS.level>oldLvl)attachToast(`<div style="color:#ffd060;letter-spacing:.32em">LVL ${oldLvl} → ${PROGRESS.level}</div><div style="font-size:11px;opacity:.7;margin-top:4px">+${gainXp} XP · +${PROGRESS.level-oldLvl} PERK PT</div>`,3500);
}
function applyUnlocks(){
  const u=PROGRESS.unlocks;
  if(u.startCredits)P.money=(P.money||0)+150;
  if(u.startHeal)P.healPacks=(P.healPacks||0)+1;
  if(u.startGrenade)P.grenades=(P.grenades||0)+1;
  if(u.extraFocus)P.focus=Math.min(1,(P.focus||1)+0.0);
}
// Per-perk runtime effect application (called at startBuilding + on attachment swap)
function applyPerks(){
  // Bigger mag perk + Extended mag attachment: stack
  for(let i=0;i<WEAPONS.length;i++){
    if(typeof WEAPONS[i]._origMag==='undefined')WEAPONS[i]._origMag=WEAPONS[i].mag;
    let m=WEAPONS[i]._origMag;
    if(hasPerk('biggerMag'))m*=1.5;
    if(P.attachments&&P.attachments.mag&&P.attachments.mag.magMul)m*=P.attachments.mag.magMul;
    WEAPONS[i].mag=Math.max(1,Math.round(m));
  }
  // Extra HP
  P.maxHp=hasPerk('extraHp')?125:100;
  P.hp=P.maxHp;
}
// Effective spread for current weapon — folds scope + muzzle + foregrip attachments
function _weaponSpreadMul(){
  let m=1.0;
  if(P.attachments){
    if(P.attachments.scope&&P.attachments.scope.spreadMul)m*=P.attachments.scope.spreadMul;
    if(P.attachments.muzzle&&P.attachments.muzzle.spreadMul)m*=P.attachments.muzzle.spreadMul;
    if(P.attachments.foregrip&&P.attachments.foregrip.spreadMul)m*=P.attachments.foregrip.spreadMul;
  }
  return m;
}
// Recoil multiplier from muzzle + foregrip attachments
function _weaponRecoilMul(){
  return _weaponRecoilMulFor(P);
}
// Is current weapon effectively suppressed? (Built-in or via muzzle attachment.)
function _weaponSuppressed(){
  return _weaponSuppressedFor(P);
}
// Improve saveProgress to track lifetime stats
function _accumulateStats(){
  PROGRESS._totalKills=(PROGRESS._totalKills||0)+P.kills;
  PROGRESS._totalHs=(PROGRESS._totalHs||0)+P.headshots;
  if(P.combo&&P.combo.peak>(PROGRESS._maxCombo||0))PROGRESS._maxCombo=P.combo.peak;
}
// ── COMBO / CHAIN SYSTEM ──────────────────────────────────────────
// Window of 4s; kills inside window grow chain. Damage taken resets unless
// "Iron Will" perk is owned.
function comboInit(){
  P.combo={count:0,timer:0,multiplier:1.0,peak:0,window:4.8};
}
function comboKill(isHead,opts={}){
  if(!P.combo)comboInit();
  P.combo.count+=1;
  P.combo.window=isHead?4.8:4.35;
  P.combo.timer=P.combo.window;
  P.combo.multiplier=Math.min(5.0,1.0+P.combo.count*.18);
  if(P.combo.count>P.combo.peak)P.combo.peak=P.combo.count;
  // Visual flair
  const el=$e('combo-hud');
  if(el){
    el.classList.add('show');
    el.querySelector('.cm-count').textContent='× '+P.combo.count;
    el.querySelector('.cm-mult').textContent=P.combo.multiplier.toFixed(2)+'×';
    el.style.transform='scale(1.035)';
    clearTimeout(P._comboPulseTimer);
    P._comboPulseTimer=setTimeout(()=>{if(el)el.style.transform='scale(1)';},90);
  }
  // Adrenal perk: kills regen focus
  const focusGain=(isHead?.09:.045)+(hasPerk('focusCharge')?.16:0)+(P.combo.count>=10?.08:0);
  P.focus=Math.min(1,(P.focus||0)+focusGain);
  applyStoryCombatReward(P,{source:(opts&&opts.source)||'combo-kill',killed:true,isHead,combo:P.combo.count,closeRange:(opts&&opts.closeRange)||0});
  if(P.combo.count%5===0&&typeof _comboMilestoneFx==='function')_comboMilestoneFx(P.combo.count);
  // Headhunter perk: extra credits on headshot
  if(isHead&&hasPerk('hsBoost')){P.money+=Math.round(20*P.combo.multiplier);}
}
function comboBreak(reason){
  if(!P.combo||P.combo.count===0)return;
  
  P.combo.count=0;P.combo.multiplier=1.0;P.combo.timer=0;P.combo.window=4.8;
  const el=$e('combo-hud');if(el)el.classList.remove('show');
}
// ── SETPIECE ROOMS — building-specific objectives that wrap a zone ────
// Each building has one setpiece active in middle zone:
//   B1 dock     → ALARM (race a 60s alarm clock for bonus credits)
//   B2 contl    → HOSTAGE (avoid friendly fire; bonus for clean clear)
//   B3 nightclb → AMBUSH (extra wave from spawn doors at 30% middle-clear)
//   B4 penthse  → SNIPER (long sightlines; reward perfect ADS streak)
//   B5 hospital → DARK ROOM (ceiling lights cut; flashlight on weapon)
//   B6 subway   → SURVIVAL (defend platform 30s before exit unlocks)
//   B7 yacht    → AMBUSH (waves from below-deck spawn doors)
//   B8 server   → ALARM (urgent — alarm timer is shorter)
const SETPIECE_DEFS={
  1:{type:'alarm',  duration:75,reward:600,name:'CONTAINMENT ALARM',desc:'Clear the middle zone before the alarm pulls reinforcements.'},
  2:{type:'hostage',count:3,reward:500,name:'HOSTAGE PROTOCOL',desc:'Civilians on the floor. No friendly fire.'},
  3:{type:'ambush', delayPct:.30,wave:4,reward:550,name:'CLUB AMBUSH',desc:'Hostiles flanking from the back rooms.'},
  4:{type:'sniper', streak:5,reward:600,name:'PRECISION HUNT',desc:'Reward streak of headshots before missing.'},
  5:{type:'dark',   reward:550,name:'BLACKOUT WARD',desc:'Power cut. Flashlight only. Stay aware.'},
  6:{type:'survival',duration:30,reward:700,name:'PLATFORM HOLD',desc:'Hold the platform until the train clears.'},
  7:{type:'ambush', delayPct:.25,wave:5,reward:650,name:'DECK BOARDED',desc:'Crew breaching from below-deck.'},
  8:{type:'alarm',  duration:55,reward:800,name:'INTRUSION DETECTED',desc:'Lockdown imminent. Move fast.'}
};
const SETPIECE={active:false,kind:null,timer:0,goal:0,progress:0,rewardGiven:false,_lastFlash:0};
// Spawn a rotating red alarm light visual (used by alarm setpieces)
function _spawnAlarmLightProp(){
  if(SETPIECE._alarm)return;
  const grp=new THREE.Group();
  // Mount on ceiling center
  grp.position.set(0,RH+WT-.30,0);
  const baseM=new THREE.MeshPhongMaterial({color:0x141414,shininess:30});
  const base=new THREE.Mesh(new THREE.CylinderGeometry(.20,.22,.10,12),baseM);
  base.position.y=.05;grp.add(base);
  // Bulb dome
  const bulbM=new THREE.MeshBasicMaterial({color:0xff2030,transparent:true,opacity:.85});
  const bulb=new THREE.Mesh(new THREE.SphereGeometry(.18,12,8,0,Math.PI*2,0,Math.PI*.6),bulbM);
  bulb.position.y=-.05;grp.add(bulb);
  // Beam fan (will rotate)
  const beamM=new THREE.MeshBasicMaterial({color:0xff5040,transparent:true,opacity:.30,blending:THREE.AdditiveBlending,depthWrite:false,side:THREE.DoubleSide});
  const beam=new THREE.Mesh(new THREE.ConeGeometry(2.5,RH-.3,12,1,true),beamM);
  beam.position.y=-(RH-.3)/2-.2;
  beam.rotation.x=Math.PI;
  grp.add(beam);
  scene.add(grp);
  SETPIECE._alarm={grp,beam,phase:0};
}
function _alarmTick(dt){
  if(!SETPIECE._alarm)return;
  SETPIECE._alarm.phase+=dt*4.5;
  SETPIECE._alarm.grp.rotation.y=SETPIECE._alarm.phase;
  // Pulse beam opacity
  if(SETPIECE._alarm.beam){
    const op=.20+Math.abs(Math.sin(SETPIECE._alarm.phase*1.4))*.30;
    SETPIECE._alarm.beam.material.opacity=op;
  }
}
function _despawnAlarmLight(){
  if(!SETPIECE._alarm)return;
  scene.remove(SETPIECE._alarm.grp);
  SETPIECE._alarm.grp.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material)o.material.dispose&&o.material.dispose();});
  SETPIECE._alarm=null;
}
function setpieceStart(bn){
  const def=SETPIECE_DEFS[bn];if(!def)return;
  SETPIECE.active=true;SETPIECE.kind=def.type;SETPIECE.def=def;
  SETPIECE.timer=def.duration||0;SETPIECE.goal=def.streak||def.count||def.wave||0;
  SETPIECE.progress=0;SETPIECE.rewardGiven=false;SETPIECE.triggered=false;
  SETPIECE._relaySilenced=false;
  // Show banner toast
  attachToast(`<div style="color:#ffd060;letter-spacing:.30em">▣ ${def.name}</div><div style="font-size:11px;opacity:.78;margin-top:4px">${def.desc}</div>`,3500);
  // Apply modifiers
  if(def.type==='alarm'){_spawnAlarmLightProp();}
  if(def.type==='dark'){
    // Dim all ceiling lights to 30% intensity, give flashlight on gun
    if(G.levelData&&G.levelData.ceilingLights){
      for(const L of G.levelData.ceilingLights){
        if(L.userData._setpieceBaseInt==null)L.userData._setpieceBaseInt=L.intensity;
        L.intensity*=.25;
      }
    }
    // Spawn flashlight cone (a SpotLight on camera)
    if(!P.flashlight){
      const fl=new THREE.SpotLight(0xfff8e0,4.5,18,Math.PI*.18,.40,1.2);
      fl.position.set(0,0,0);
      const tgt=new THREE.Object3D();tgt.position.set(0,0,-1);
      camera.add(fl);camera.add(tgt);fl.target=tgt;
      P.flashlight=fl;P.flashTarget=tgt;
    }
  }
  if(def.type==='hostage'){
    // Spawn 3 hostage props in middle zone (kneeling civilians)
    SETPIECE._hostages=[];
    const civM=new THREE.MeshLambertMaterial({color:0xc8a070});
    const shirtM=new THREE.MeshLambertMaterial({color:0x506080});
    for(let i=0;i<def.count;i++){
      const grp=new THREE.Group();
      const px=(-3+i*3),pz=2-(i*2.2);
      grp.position.set(px,WT,pz);scene.add(grp);
      // Body kneeling
      grp.add(new THREE.Mesh(new THREE.BoxGeometry(.42,.65,.30),shirtM)).position.set(0,.45,0);
      // Head
      const hd=new THREE.Mesh(new THREE.BoxGeometry(.24,.24,.24),civM);hd.position.set(0,.95,0);grp.add(hd);
      // Arms behind (raised)
      const aL=new THREE.Mesh(new THREE.BoxGeometry(.10,.28,.10),shirtM);aL.position.set(.18,.78,-.05);aL.rotation.x=-.55;grp.add(aL);
      const aR=new THREE.Mesh(new THREE.BoxGeometry(.10,.28,.10),shirtM);aR.position.set(-.18,.78,-.05);aR.rotation.x=-.55;grp.add(aR);
      grp.userData.isHostage=true;
      SETPIECE._hostages.push(grp);
    }
  }
}
function setpieceTickProgress(){
  // Called when middle-zone enemy count drops — used for ambush trigger
  if(!SETPIECE.active||SETPIECE.triggered)return;
  if(SETPIECE.kind!=='ambush')return;
  if(!G.enemyMgr||!G.zoneClears)return;
  const aliveMid=G.enemyMgr._list.filter(e=>!e.dead&&e.zoneId===1).length;
  const total=G.enemyMgr._list.filter(e=>e.zoneId===1).length;
  const pct=1-aliveMid/Math.max(1,total);
  if(pct>=(SETPIECE.def.delayPct||.30)){
    SETPIECE.triggered=true;
    // Spawn extra wave through spawn doors in middle zone
    const sd=G.levelData&&G.levelData.spawnDoors||[];
    const _walls=G.levelData?G.levelData.walls:[];
    const peers=[];
    for(const e of G.enemyMgr._list){if(e&&!e.dead&&e.group)peers.push({x:e.group.position.x,z:e.group.position.z});}
    for(let i=0;i<SETPIECE.def.wave;i++){
      const door=sd.filter(d=>d.zoneId===1)[i%2];
      if(!door)break;
      const id=1.14;
      const bx=door.ax+door.inwardX*id,bz=door.az+door.inwardZ*id;
      const types=['scout','soldier','soldier','pistolero','riot'];
      const type=types[i%types.length];
      const opts={zoneId:1,peerR:_enemySpawnPeerRadius(type),requireNav:true,strictZone:false};
      const pos=_snapSpawnOutOfWalls(bx,bz,WT,_walls,.46,peers,opts)
        ||_findClearEnemySpawn(new THREE.Vector3(bx,WT,bz),_walls,.46,peers,opts);
      if(!pos)continue;
      const e=new Enemy(scene,pos,Math.min(4,G.building+1),type);
      e.zoneId=1;e.spawnIntro={t:0,door};
      G.enemyMgr._list.push(e);
      peers.push({x:pos.x,z:pos.z});
      G.enemyMgr._needsSpawnAudit=true;
    }
    G.enemyMgr._repairSpawnOverlaps(_walls);
    G.enemyMgr._needsSpawnAudit=false;
    _flagSsrSolidsDirty();
    attachToast('<div style="color:#ff5048;letter-spacing:.30em">▼ AMBUSH</div>',2000);
  }
}
function setpieceTick(dt){
  if(!SETPIECE.active)return;
  _alarmTick(dt);
  // Hostage idle wave / cower animation
  if(SETPIECE._hostages){
    for(const h of SETPIECE._hostages){
      h.userData._t=(h.userData._t||0)+dt;
      h.position.y=WT+Math.sin(h.userData._t*1.4)*.012;
      // Slight head tremble
      if(h.children[1])h.children[1].rotation.z=Math.sin(h.userData._t*3.5)*.04;
    }
  }
  // Alarm — countdown; if timer hits 0, lose reward and spawn extra wave
  if(SETPIECE.kind==='alarm'){
    if(!SETPIECE._relaySilenced)SETPIECE.timer-=dt;
    if(SETPIECE.timer<=0&&!SETPIECE.triggered&&!SETPIECE._relaySilenced){
      SETPIECE.triggered=true;
      if(G.mastery){G.mastery.failed=true;G.levelState&&(G.levelState.masteryFailed=true);}
      attachToast('<div style="color:#ff5048;letter-spacing:.30em">! REINFORCEMENTS</div>',2200);
      // Spawn extra wave
      const sd=G.levelData&&G.levelData.spawnDoors||[];
      const _walls=G.levelData?G.levelData.walls:[];
      const peers=[];
      for(const e of G.enemyMgr._list){if(e&&!e.dead&&e.group)peers.push({x:e.group.position.x,z:e.group.position.z});}
      for(let i=0;i<3;i++){
        const door=sd[i%sd.length];if(!door)break;
        const id=1.14;
        const bx=door.ax+door.inwardX*id,bz=door.az+door.inwardZ*id;
        const type=i===0?'heavy':'soldier';
        const opts={zoneId:Math.min(2,door.zoneId+1),peerR:_enemySpawnPeerRadius(type),requireNav:true,strictZone:false};
        const pos=_snapSpawnOutOfWalls(bx,bz,WT,_walls,.46,peers,opts)
          ||_findClearEnemySpawn(new THREE.Vector3(bx,WT,bz),_walls,.46,peers,opts);
        if(!pos)continue;
        const e=new Enemy(scene,pos,Math.min(4,G.building+1),type);
        e.zoneId=Math.min(2,door.zoneId+1);e.spawnIntro={t:0,door};
        G.enemyMgr._list.push(e);
        peers.push({x:pos.x,z:pos.z});
        G.enemyMgr._needsSpawnAudit=true;
      }
      G.enemyMgr._repairSpawnOverlaps(_walls);
      G.enemyMgr._needsSpawnAudit=false;
      _flagSsrSolidsDirty();
    }
    // Update HUD timer (reuse compass-area or attach toast intermittently)
    const sb=$e('setpiece-bar');if(sb){
      const ratio=Math.max(0,SETPIECE.timer/SETPIECE.def.duration);
      sb.querySelector('.sp-fill').style.width=(ratio*100).toFixed(1)+'%';
      sb.querySelector('.sp-time').textContent=Math.max(0,Math.ceil(SETPIECE.timer))+'s';
      sb.classList.add('show');
    }
  }
  if(SETPIECE.kind==='survival'){
    SETPIECE.timer+=dt;
    const sb=$e('setpiece-bar');if(sb){
      const ratio=Math.min(1,SETPIECE.timer/SETPIECE.def.duration);
      sb.querySelector('.sp-fill').style.width=(ratio*100).toFixed(1)+'%';
      sb.querySelector('.sp-time').textContent=Math.max(0,Math.ceil(SETPIECE.def.duration-SETPIECE.timer))+'s';
      sb.classList.add('show');
    }
    if(SETPIECE.timer>=SETPIECE.def.duration&&!SETPIECE.rewardGiven){
      SETPIECE.rewardGiven=true;
      P.money+=SETPIECE.def.reward;
      moneyPopup(SETPIECE.def.reward,'HELD');
      attachToast('<div style="color:#5fcb52;letter-spacing:.30em">✓ HELD</div>',1800);
    }
  }
  if(SETPIECE.kind==='ambush'){
    setpieceTickProgress();
  }
}
function setpieceCheckHostageHit(target){
  // Called from any damage path that could hit a hostage
  if(SETPIECE.active&&SETPIECE.kind==='hostage'&&target&&target.userData&&target.userData.isHostage){
    SETPIECE.progress+=1;
    if(G.mastery){G.mastery.failed=true;G.levelState&&(G.levelState.masteryFailed=true);}
    attachToast('<div style="color:#ff5048;letter-spacing:.30em">! HOSTAGE HIT</div>',1500);
  }
}
function setpieceOnZoneCleared(zid){
  if(!SETPIECE.active||SETPIECE.rewardGiven)return;
  // Reward awarded after middle zone clear (most setpieces wrap zone 1)
  const cleared=G.zoneClears&&G.zoneClears[1];
  if(zid===1&&cleared){
    let reward=SETPIECE.def.reward;
    let label='OBJECTIVE';
    if(SETPIECE.kind==='alarm'&&SETPIECE.timer>0){label='ALARM SILENCED';}
    if(SETPIECE.kind==='hostage'){
      if(SETPIECE.progress===0){label='CIVILIANS SAFE';reward=Math.round(reward*1.3);}
      else{reward=Math.max(0,reward-200*SETPIECE.progress);label='OBJECTIVE';}
    }
    if(SETPIECE.kind==='dark'){label='BLACKOUT';}
    if(SETPIECE.kind==='sniper'&&SETPIECE.progress>=SETPIECE.goal){label='PRECISION';reward=Math.round(reward*1.5);}
    if(reward>0){P.money+=reward;moneyPopup(reward,label);}
    SETPIECE.rewardGiven=true;
  }
}
function setpieceEnd(){
  const wasDark=SETPIECE.kind==='dark';
  SETPIECE.active=false;SETPIECE.kind=null;
  _despawnAlarmLight();
  const sb=$e('setpiece-bar');if(sb)sb.classList.remove('show');
  // Restore lights if dark mode was active
  if(wasDark&&G.levelData&&G.levelData.ceilingLights){
    for(const L of G.levelData.ceilingLights){
      if(L.userData&&L.userData._setpieceBaseInt!=null){L.intensity=L.userData._setpieceBaseInt;delete L.userData._setpieceBaseInt;}
    }
  }
  if(P.flashlight){
    camera.remove(P.flashlight);
    if(P.flashTarget)camera.remove(P.flashTarget);
    P.flashlight=null;P.flashTarget=null;
  }
  if(SETPIECE._hostages){
    SETPIECE._hostages.forEach(h=>scene.remove(h));
    SETPIECE._hostages=null;
  }
}
function comboTick(dt){
  if(!P.combo)comboInit();
  if(P.combo.count>0){
    P.combo.timer-=dt;
    const el=$e('combo-hud');
    if(el){
      const fill=el.querySelector('.cm-fill');
      if(fill)fill.style.width=Math.max(0,P.combo.timer/(P.combo.window||4.8)*100).toFixed(0)+'%';
    }
    if(P.combo.timer<=0)comboBreak('timeout');
  }
}
// ── TAKE-DOWN / EXECUTION SYSTEM ────────────────────────────────────
// Press T near a low-HP enemy in front cone to perform a scripted execution.
// Different animations per equipped weapon. Brief slow-mo + i-frames.
const TAKEDOWN={
  active:false,
  t:0,
  startedAt:0,
  dur:1.26,
  killAt:.58,
  target:null,
  startCamPos:null,
  startCamQuat:null,
  startPlayerPos:null,
  endPlayerPos:null,
  targetStartPos:null,
  targetStartYaw:0,
  startYaw:0,
  targetYaw:0,
  iframeUntil:0,
  style:'gun',
  side:1,
  grabDone:false,
  controlDone:false,
  impactDone:false,
  rewardDone:false,
  label:'EXECUTE',
  contactRig:null
};
function _takedownEase01(v){return THREE.MathUtils.smoothstep(THREE.MathUtils.clamp(v,0,1),0,1);}
function _takedownLabelForWeapon(idx){
  if(idx===2)return 'KNIFE STAB';
  if(idx===1||idx===6)return 'PISTOL DISARM';
  if(idx===3)return 'STOCK BREAK';
  if(idx===4||idx===5||idx===0||idx===7)return 'RIFLE STRIKE';
  return 'TAKEDOWN';
}
const _TD_AXIS_Y=new THREE.Vector3(0,1,0);
function _tdLerpVec(a,b,t){
  return new THREE.Vector3(
    THREE.MathUtils.lerp(a.x,b.x,t),
    THREE.MathUtils.lerp(a.y,b.y,t),
    THREE.MathUtils.lerp(a.z,b.z,t)
  );
}
function _tdPoint(base,into,right,ix,rx,y){
  return new THREE.Vector3(base.x+into.x*ix+right.x*rx,y,base.z+into.z*ix+right.z*rx);
}
function _tdPoseBar(mesh,a,b,thick=.065){
  if(!mesh)return;
  const dx=b.x-a.x,dy=b.y-a.y,dz=b.z-a.z;
  const len=Math.hypot(dx,dy,dz);
  if(len<.012){mesh.visible=false;return;}
  mesh.visible=true;
  mesh.position.set((a.x+b.x)*.5,(a.y+b.y)*.5,(a.z+b.z)*.5);
  mesh.scale.set(thick,len,thick);
  mesh.quaternion.setFromUnitVectors(_TD_AXIS_Y,new THREE.Vector3(dx/len,dy/len,dz/len));
}
function _tdSetBall(mesh,pos,sx=.13,sy=.10,sz=.12){
  if(!mesh)return;
  mesh.visible=true;
  mesh.position.copy(pos);
  mesh.scale.set(sx,sy,sz);
}
function _ensureTakedownContactRig(){
  if(TAKEDOWN.contactRig)return TAKEDOWN.contactRig;
  const rig=new THREE.Group();
  rig.name='TakedownContactRig';
  rig.visible=false;
  rig.userData.impactPulse=0;
  rig.userData.controlPulse=0;
  const sleeveMat=new THREE.MeshStandardMaterial({color:0x111821,roughness:.78,metalness:.08});
  const gloveMat=new THREE.MeshStandardMaterial({color:0x050608,roughness:.62,metalness:.12});
  const hardMat=new THREE.MeshStandardMaterial({color:0x1d2024,roughness:.45,metalness:.35});
  const bladeMat=new THREE.MeshStandardMaterial({color:0xd6e4ef,roughness:.28,metalness:.70,emissive:0x102030,emissiveIntensity:.12});
  const flashMat=new THREE.MeshBasicMaterial({color:0xffefe0,transparent:true,opacity:.0,depthWrite:false,blending:THREE.AdditiveBlending});
  const boxGeo=new THREE.BoxGeometry(1,1,1);
  const handGeo=new THREE.SphereGeometry(1,12,8);
  const flashGeo=new THREE.SphereGeometry(1,14,8);
  const makeBar=(name,mat)=>{const m=new THREE.Mesh(boxGeo,mat);m.name=name;m.frustumCulled=false;m.castShadow=false;m.receiveShadow=false;rig.add(m);return m;};
  const makeHand=(name)=>{const m=new THREE.Mesh(handGeo,gloveMat);m.name=name;m.frustumCulled=false;m.castShadow=false;m.receiveShadow=false;rig.add(m);return m;};
  const parts={
    leadUpper:makeBar('leadUpper',sleeveMat),
    leadFore:makeBar('leadFore',sleeveMat),
    strikeUpper:makeBar('strikeUpper',sleeveMat),
    strikeFore:makeBar('strikeFore',sleeveMat),
    leadHand:makeHand('leadHand'),
    strikeHand:makeHand('strikeHand'),
    tool:makeBar('strikeTool',hardMat),
    blade:makeBar('knifeBlade',bladeMat),
    flash:new THREE.Mesh(flashGeo,flashMat)
  };
  parts.flash.name='impactFlash';
  parts.flash.visible=false;
  parts.flash.frustumCulled=false;
  rig.add(parts.flash);
  rig.userData.parts=parts;
  scene.add(rig);
  TAKEDOWN.contactRig=rig;
  return rig;
}
function _hideTakedownContactRig(){
  const rig=TAKEDOWN.contactRig;
  if(!rig)return;
  rig.visible=false;
  const parts=rig.userData&&rig.userData.parts;
  if(parts){
    Object.values(parts).forEach(p=>{if(p)p.visible=false;});
  }
}
function _updateTakedownContactRig(target,ph,into,right,dt){
  const rig=_ensureTakedownContactRig();
  if(!target||!target.group){_hideTakedownContactRig();return;}
  const parts=rig.userData.parts;
  rig.visible=true;
  const side=TAKEDOWN.side||1;
  const player=P.pos;
  const targetBase=target.group.position;
  const grab=THREE.MathUtils.smoothstep(ph,.10,.32)*(1-THREE.MathUtils.smoothstep(ph,.78,1));
  const control=THREE.MathUtils.smoothstep(ph,.25,.46)*(1-THREE.MathUtils.smoothstep(ph,.80,1));
  const strikeIn=THREE.MathUtils.smoothstep(ph,.38,TAKEDOWN.killAt);
  const strikeRecover=THREE.MathUtils.smoothstep(ph,TAKEDOWN.killAt,.86);
  const drop=THREE.MathUtils.smoothstep(ph,.64,1);
  const wind=1-THREE.MathUtils.smoothstep(ph,.02,.25);
  const leadShoulder=_tdPoint(player,into,right,.14,side*.25,1.06+wind*.02-drop*.03);
  const strikeShoulder=_tdPoint(player,into,right,.12,-side*.25,1.03+wind*.05-drop*.02);
  const grabPoint=_tdPoint(targetBase,into,right,-.22,side*.18,1.36-drop*.16);
  const pinPoint=_tdPoint(targetBase,into,right,-.18,side*.12,1.48-drop*.20);
  const hitPoint=_tdPoint(targetBase,into,right,-.12,-side*.055,TAKEDOWN.style==='knife'?1.33:1.18);
  const windPoint=_tdPoint(player,into,right,-.10,-side*.43,1.30+wind*.16);
  const followPoint=_tdPoint(targetBase,into,right,.12,-side*.10,TAKEDOWN.style==='knife'?1.16:1.06);
  const leadStart=_tdPoint(player,into,right,.18,side*.34,1.02);
  const leadHand=_tdLerpVec(leadStart,_tdLerpVec(grabPoint,pinPoint,control*.45),grab);
  leadHand.y-=drop*.18;
  const strikeTarget=_tdLerpVec(windPoint,hitPoint,strikeIn);
  const strikeHand=_tdLerpVec(strikeTarget,followPoint,strikeRecover);
  strikeHand.y-=drop*.08;
  const leadElbow=_tdLerpVec(leadShoulder,leadHand,.48);
  leadElbow.addScaledVector(right,side*.10).addScaledVector(into,-.04);
  leadElbow.y-=.12;
  const strikeElbow=_tdLerpVec(strikeShoulder,strikeHand,.46);
  strikeElbow.addScaledVector(right,-side*(.12+wind*.08)).addScaledVector(into,-.08);
  strikeElbow.y-=.10-wind*.04;
  _tdPoseBar(parts.leadUpper,leadShoulder,leadElbow,.076);
  _tdPoseBar(parts.leadFore,leadElbow,leadHand,.070);
  _tdPoseBar(parts.strikeUpper,strikeShoulder,strikeElbow,.078);
  _tdPoseBar(parts.strikeFore,strikeElbow,strikeHand,.072);
  _tdSetBall(parts.leadHand,leadHand,.13,.09,.11);
  _tdSetBall(parts.strikeHand,strikeHand,.14,.095,.12);
  if(parts.tool){
    const toolTip=_tdLerpVec(strikeHand,hitPoint,.82);
    toolTip.addScaledVector(into,TAKEDOWN.style==='knife'?.16:.08);
    _tdPoseBar(parts.tool,strikeHand,toolTip,TAKEDOWN.style==='knife'?.040:.105);
    parts.tool.visible=TAKEDOWN.style!=='knife';
  }
  if(parts.blade){
    const bladeBase=strikeHand.clone().addScaledVector(into,.04);
    const bladeTip=hitPoint.clone().addScaledVector(into,.18);
    _tdPoseBar(parts.blade,bladeBase,bladeTip,.030);
    parts.blade.visible=TAKEDOWN.style==='knife';
  }
  rig.userData.impactPulse=damp(rig.userData.impactPulse||0,0,12,dt);
  rig.userData.controlPulse=damp(rig.userData.controlPulse||0,0,10,dt);
  const flashPulse=Math.max(rig.userData.impactPulse||0,(rig.userData.controlPulse||0)*.48);
  if(parts.flash){
    parts.flash.visible=flashPulse>.025;
    parts.flash.position.copy((rig.userData.impactPulse||0)>.1?hitPoint:grabPoint);
    const s=.12+flashPulse*.42;
    parts.flash.scale.set(s,s*.62,s);
    if(parts.flash.material)parts.flash.material.opacity=Math.min(.78,flashPulse*.70);
  }
  rig.userData.phase=ph;
  rig.userData.visible=true;
}
function _sfxTakedownBeat(kind){
  const c=getAC();
  const o=c.createOscillator(),g=c.createGain();
  o.type=kind==='impact'?'sawtooth':'triangle';
  const f0=kind==='grab'?150:kind==='control'?115:88;
  const f1=kind==='grab'?62:kind==='control'?48:34;
  o.frequency.setValueAtTime(f0,c.currentTime);
  o.frequency.exponentialRampToValueAtTime(f1,c.currentTime+.16);
  g.gain.setValueAtTime(kind==='impact'?.24:.13,c.currentTime);
  g.gain.exponentialRampToValueAtTime(.001,c.currentTime+(kind==='impact'?.20:.14));
  o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.22);
}
function _triggerTakedownBeat(kind){
  const t=TAKEDOWN.target;
  if(!TAKEDOWN.active||!t)return;
  const td=t._takedownVictim;
  if(td){
    td.beat=kind;
    if(kind==='grab')td.grabPulse=1;
    if(kind==='control')td.controlPulse=1;
    if(kind==='impact')td.impactPulse=1;
  }
  const rig=_ensureTakedownContactRig();
  if(rig&&rig.userData){
    if(kind==='grab'||kind==='control')rig.userData.controlPulse=Math.max(rig.userData.controlPulse||0,kind==='grab'?.85:1);
    if(kind==='impact')rig.userData.impactPulse=Math.max(rig.userData.impactPulse||0,1);
  }
  if(kind==='grab'){
    PP.shakeX+=TAKEDOWN.side*.045;
    PP.shakeY-=.055;
    P._takedownGrabPulse=Math.max(P._takedownGrabPulse||0,1);
  }else if(kind==='control'){
    PP.shakeX-=TAKEDOWN.side*.060;
    PP.shakeY-=.070;
    P._takedownControlPulse=Math.max(P._takedownControlPulse||0,1);
  }else if(kind==='impact'){
    P._takedownImpactPulse=Math.max(P._takedownImpactPulse||0,1);
  }
  _sfxTakedownBeat(kind);
}
function _tryFindTakedownTarget(){
  if(!G.enemyMgr)return null;
  // Player forward dir
  const fx=-Math.sin(P.yaw),fz=-Math.cos(P.yaw);
  const nowMs=performance.now();
  let best=null,bestScore=99;
  for(const e of G.enemyMgr._list){
    if(e.dead||e.removeNeeded)continue;
    const dx=e.group.position.x-P.pos.x,dz=e.group.position.z-P.pos.z;
    const d=Math.sqrt(dx*dx+dz*dz);
    const finishable=!!(e._finishableUntil&&nowMs<e._finishableUntil&&e._finishableTakedown);
    const maxD=finishable?2.82:2.4;
    if(d>maxD)continue;
    // Must be in forward cone
    const facing=(dx*fx+dz*fz)/Math.max(d,.01);
    if(facing<(finishable?.42:.55))continue;
    // Must be low HP (≤35% of max) OR boss-style takedown disabled
    if(e.isBoss)continue;
    const ratio=e.hp/Math.max(1,e.maxHp);
    if(ratio>.35&&!finishable)continue;
    if(finishable&&ratio>.68)continue;
    const pain=finishable&&e._finishableTakedown?e._finishableTakedown.pain||0:0;
    const score=d-facing*.30-pain*.36-(finishable?.32:0);
    if(score<bestScore){bestScore=score;best=e;}
  }
  return best;
}
function tryTakedown(){
  if(P.dead||TAKEDOWN.active||MELEE.out||TK.active||GR.active)return false;
  const target=_tryFindTakedownTarget();
  if(!target)return false;
  if(P.reloading){
    recordReloadInterruptFeel(P,{weaponIdx:P.weaponIdx,reason:'takedown-cancel',nowMs:performance.now()});
    P.reloading=false;
    reloadHoloTarget=0;
    const rb=$e('reload-bar');if(rb)rb.style.display='none';
  }
  const startPos=P.pos.clone();
  const targetPos=target.group.position.clone();
  let into=new THREE.Vector3(targetPos.x-startPos.x,0,targetPos.z-startPos.z);
  if(into.lengthSq()<.0001)into.set(-Math.sin(P.yaw),0,-Math.cos(P.yaw));
  into.normalize();
  const right=new THREE.Vector3(into.z,0,-into.x);
  const side=(Math.random()<.5?-1:1);
  const approachDist=P.weaponIdx===3?.98:.82;
  const endPos=targetPos.clone().addScaledVector(into,-approachDist).addScaledVector(right,side*.08);
  endPos.y=startPos.y;
  const targetYaw=Math.atan2(-into.x,-into.z);
  TAKEDOWN.active=true;TAKEDOWN.t=0;TAKEDOWN.startedAt=performance.now();TAKEDOWN.target=target;
  TAKEDOWN.style=(P.weaponIdx===2)?'knife':P.weaponIdx===1?'pistol':'gun';
  TAKEDOWN.side=side;
  TAKEDOWN.grabDone=false;
  TAKEDOWN.controlDone=false;
  TAKEDOWN.impactDone=false;
  TAKEDOWN.rewardDone=false;
  TAKEDOWN.label=_takedownLabelForWeapon(P.weaponIdx);
  TAKEDOWN.startCamPos=camera.position.clone();
  TAKEDOWN.startCamQuat=camera.quaternion.clone();
  TAKEDOWN.startPlayerPos=startPos;
  TAKEDOWN.endPlayerPos=endPos;
  TAKEDOWN.targetStartPos=targetPos;
  TAKEDOWN.targetStartYaw=target.group.rotation.y||0;
  TAKEDOWN.startYaw=P.yaw;
  TAKEDOWN.targetYaw=targetYaw;
  TAKEDOWN.iframeUntil=performance.now()+Math.round(TAKEDOWN.dur*1000)+180;
	  target._takedownVictim={
	    style:TAKEDOWN.style,
	    side,
	    phase:0,
	    until:performance.now()+Math.round(TAKEDOWN.dur*1000)+260,
	    startYaw:target.group.rotation.y||0,
	    finishable:target._finishableTakedown||null,
	    impact:false,
	    beat:'start',
    grabPulse:0,
    controlPulse:0,
    impactPulse:0
  };
	  target._suppressedUntil=Math.max(target._suppressedUntil||0,performance.now()+Math.round(TAKEDOWN.dur*1000)+420);
	  target._finishableUntil=0;
	  target._incomingNearMiss=Math.max(target._incomingNearMiss||0,.85);
  target._suppressionFlinchPulse=Math.max(target._suppressionFlinchPulse||0,.75);
  target.shootTimer=Math.max(target.shootTimer||0,TAKEDOWN.dur+.4);
  target.burstCooldown=Math.max(target.burstCooldown||0,TAKEDOWN.dur+.4);
  target.aimReady=0;
  MELEE.out=true;
  _whipActive=false;
  if(throwGrp)throwGrp.visible=false;
  _ensureTakedownContactRig();
  playerAnimEmitNotify(playerAnimState0,_playerAnimFrameSeq,'meleeStart',{execution:true,style:TAKEDOWN.style});
  // Half-speed time during execution
  triggerKillCamSlowMo(.35,TAKEDOWN.dur);
  sfxTakedown();
  return true;
}
function _finishTakedownImpact(){
  const t=TAKEDOWN.target;
  if(!TAKEDOWN.active||TAKEDOWN.impactDone||!t)return;
  TAKEDOWN.impactDone=true;
  TAKEDOWN.rewardDone=true;
  if(t._takedownVictim){
    t._takedownVictim.impact=true;
    t._takedownVictim.beat='impact';
    t._takedownVictim.impactPulse=1;
  }
  _triggerTakedownBeat('impact');
  playerAnimEmitNotify(playerAnimState0,_playerAnimFrameSeq,'meleeImpactFrame',{execution:true,style:TAKEDOWN.style});
  const hitPt=t.group.position.clone();
  hitPt.y+=TAKEDOWN.style==='knife'?1.36:1.18;
  try{addBlood(hitPt,true);}catch(_){}
  try{addParticle(hitPt,true);}catch(_){}
  try{spawnSlashFx(true,TAKEDOWN.style==='knife'?3:2);}catch(_){}
  if(typeof triggerHitStop==='function')triggerHitStop(62);
  const kb=$e('kill-beat');if(kb){kb.style.opacity='.95';setTimeout(()=>kb.style.opacity='0',90);}
  PP.shakeX+=TAKEDOWN.side*.22;
  PP.shakeY-=.38;
  P.dmgPitch+=.045;
  P._takedownImpactPulse=Math.max(P._takedownImpactPulse||0,1);
  if(!t.dead){
    Enemy._nextHitFlags={suppressed:true,takedown:true,weaponIdx:P.weaponIdx,impactWeight:1.55,enemyAimBreak:1.4,enemyStagger:1.7,enemyPush:1.35};
    _primeEnemyHitZone(TAKEDOWN.style==='knife'?'neck':'head');
    t.takeDamage(9999,true,true);
  }
  let bonus=400;
  if(hasPerk('execMaster')){bonus+=250;P.hp=Math.min(P.maxHp||100,P.hp+22);}
  P.money+=bonus;moneyPopup(bonus,TAKEDOWN.label);
  P.execs=(P.execs||0)+1;
  P.kills++;P.headshots++;
  comboKill(true,{source:'takedown-kill',closeRange:1});
  applyStoryMomentumShock(t,t.group.position,{source:'takedown-kill',isHead:true});
  killFeed(true,{exec:true,dist:t.group.position.distanceTo(camera.position)});
  attachToast(`<div style="color:#ff5048;letter-spacing:.30em">▼ ${TAKEDOWN.label}</div><div style="font-size:12px;margin-top:3px">+$${bonus}</div>`,1800);
  checkZoneClears();
}
function sfxTakedown(){
  const c=getAC();
  // Heavy thump + breath + impact
  const o=c.createOscillator(),g=c.createGain();
  o.type='sine';o.frequency.setValueAtTime(60,c.currentTime);
  o.frequency.exponentialRampToValueAtTime(28,c.currentTime+.30);
  g.gain.setValueAtTime(.55,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.32);
  o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.35);
  const w=c.createOscillator(),wg=c.createGain();
  w.type='triangle';w.frequency.setValueAtTime(190,c.currentTime+.08);
  w.frequency.exponentialRampToValueAtTime(88,c.currentTime+.30);
  wg.gain.setValueAtTime(.001,c.currentTime);
  wg.gain.linearRampToValueAtTime(.18,c.currentTime+.09);
  wg.gain.exponentialRampToValueAtTime(.001,c.currentTime+.32);
  w.connect(wg);wg.connect(c.destination);w.start(c.currentTime+.04);w.stop(c.currentTime+.35);
}
function updateTakedown(dt){
  if(!TAKEDOWN.active)return;
  TAKEDOWN.t=(performance.now()-(TAKEDOWN.startedAt||performance.now()))/1000;
  const t=TAKEDOWN.target;
  if(!t){
    TAKEDOWN.active=false;TAKEDOWN.target=null;MELEE.out=false;P._takedownPhase=0;
    P._takedownViewmodelDrive=0;
    P._takedownGrabPulse=0;
    P._takedownControlPulse=0;
    _hideTakedownContactRig();
    return;
  }
  const ph=THREE.MathUtils.clamp(TAKEDOWN.t/TAKEDOWN.dur,0,1);
  if(ph>=.24&&!TAKEDOWN.grabDone){TAKEDOWN.grabDone=true;_triggerTakedownBeat('grab');}
  if(ph>=.42&&!TAKEDOWN.controlDone){TAKEDOWN.controlDone=true;_triggerTakedownBeat('control');}
  if(ph>=TAKEDOWN.killAt&&!TAKEDOWN.impactDone)_finishTakedownImpact();
  // Camera locks toward the original player-to-target line. Using the moving
  // endpoint here can spin the view past the enemy during the lunge.
  const tx=(TAKEDOWN.targetStartPos||t.group.position).x,tz=(TAKEDOWN.targetStartPos||t.group.position).z;
  const anchor=TAKEDOWN.startPlayerPos||P.pos;
  let into=new THREE.Vector3(tx-anchor.x,0,tz-anchor.z);
  if(into.lengthSq()<.0001)into.set(-Math.sin(P.yaw),0,-Math.cos(P.yaw));
  into.normalize();
  const right=new THREE.Vector3(into.z,0,-into.x);
  const baseYaw=Number.isFinite(TAKEDOWN.targetYaw)?TAKEDOWN.targetYaw:Math.atan2(-into.x,-into.z);
  const orbit=Math.sin(ph*Math.PI)*TAKEDOWN.side*.050*(1-THREE.MathUtils.smoothstep(ph,.76,1));
  const grabSnap=(TAKEDOWN.grabDone&&!TAKEDOWN.impactDone)?Math.sin(THREE.MathUtils.clamp((ph-.24)/.20,0,1)*Math.PI)*TAKEDOWN.side*.018:0;
  const aimYaw=baseYaw+orbit+grabSnap;
  P.yaw=dampAngle(P.yaw,aimYaw,ph<.18?20:13,dt);
  P._takedownAimYaw=aimYaw;
  if(TAKEDOWN.startPlayerPos&&TAKEDOWN.endPlayerPos){
    const lunge=_takedownEase01((ph-.04)/.34);
    const settleBack=THREE.MathUtils.smoothstep(ph,.72,1);
    const blend=Math.max(0,lunge-settleBack*.16);
    P.pos.x=THREE.MathUtils.lerp(TAKEDOWN.startPlayerPos.x,TAKEDOWN.endPlayerPos.x,blend);
    P.pos.z=THREE.MathUtils.lerp(TAKEDOWN.startPlayerPos.z,TAKEDOWN.endPlayerPos.z,blend);
  }
  if(TAKEDOWN.targetStartPos&&t.group){
    const recoil=TAKEDOWN.impactDone?Math.sin(THREE.MathUtils.clamp((ph-TAKEDOWN.killAt)/.32,0,1)*Math.PI)*.18:0;
    t.group.position.x=TAKEDOWN.targetStartPos.x+into.x*recoil;
    t.group.position.z=TAKEDOWN.targetStartPos.z+into.z*recoil;
    t.group.rotation.y=Math.atan2(P.pos.x-t.group.position.x,P.pos.z-t.group.position.z);
  }
  _updateTakedownContactRig(t,ph,into,right,dt);
  const wind=1-THREE.MathUtils.smoothstep(ph,.00,.24);
  const strike=1-Math.abs(THREE.MathUtils.clamp((ph-TAKEDOWN.killAt)/.20,-1,1));
  const recover=THREE.MathUtils.smoothstep(ph,.70,1);
  const grabPulse=Number.isFinite(P._takedownGrabPulse)?P._takedownGrabPulse:0;
  const controlPulse=Number.isFinite(P._takedownControlPulse)?P._takedownControlPulse:0;
  P._takedownPhase=ph;
  P._takedownSide=TAKEDOWN.side;
  P._takedownStyle=TAKEDOWN.style;
  P._takedownCameraPitch=-wind*.020+Math.sin(ph*Math.PI)*.038+strike*.034+grabPulse*.010+controlPulse*.012-recover*.010;
  P._takedownCameraRoll=TAKEDOWN.side*(wind*.030+strike*.085+grabPulse*.025-controlPulse*.020-recover*.020);
  P._takedownViewmodelDrive=Math.max(wind*.45,strike,grabPulse*.40,controlPulse*.35);
  P._takedownGrabPulse=damp(grabPulse,0,10,dt);
  P._takedownControlPulse=damp(controlPulse,0,10,dt);
  P._takedownImpactPulse=damp(Number.isFinite(P._takedownImpactPulse)?P._takedownImpactPulse:0,0,8,dt);
  if(t._takedownVictim){
    t._takedownVictim.phase=ph;
    t._takedownVictim.impact=TAKEDOWN.impactDone;
    t._takedownVictim.grabPulse=damp(Number.isFinite(t._takedownVictim.grabPulse)?t._takedownVictim.grabPulse:0,0,9,dt);
    t._takedownVictim.controlPulse=damp(Number.isFinite(t._takedownVictim.controlPulse)?t._takedownVictim.controlPulse:0,0,9,dt);
    t._takedownVictim.impactPulse=damp(Number.isFinite(t._takedownVictim.impactPulse)?t._takedownVictim.impactPulse:0,0,8,dt);
    t._takedownVictim.until=Math.max(t._takedownVictim.until||0,performance.now()+220);
    t.group.userData.takedownVictim={
      phase:ph,
      beat:t._takedownVictim.beat||'',
      style:TAKEDOWN.style,
      contactRigVisible:!!(TAKEDOWN.contactRig&&TAKEDOWN.contactRig.visible)
    };
  }
  // Camera dip in middle of animation
  const dip=Math.sin(ph*Math.PI)*.05;
  PP.shakeY-=dip*.22;
  if(TAKEDOWN.t>=TAKEDOWN.dur){
    if(!TAKEDOWN.impactDone)_finishTakedownImpact();
    if(t&&t._takedownVictim)t._takedownVictim.until=performance.now()+120;
    TAKEDOWN.active=false;TAKEDOWN.target=null;MELEE.out=false;
    P._takedownPhase=0;
    P._takedownViewmodelDrive=0;
    P._takedownGrabPulse=0;
    P._takedownControlPulse=0;
    _hideTakedownContactRig();
    playerAnimEmitNotify(playerAnimState0,_playerAnimFrameSeq,'meleeEnd',{execution:true,style:TAKEDOWN.style});
  }
}
// ── DODGE ROLL ──────────────────────────────────────────────────────
const DODGE={active:false,t:0,dur:.50,vx:0,vz:0,iframeUntil:0};
let _lastDodgeKey={code:null,t:0};
function tryDodge(dirCode){
  if(!hasPerk('dodgeRoll'))return;
  if(P.dead||DODGE.active||P.vaulting||TAKEDOWN.active)return;
  if((P.focus||0)<.18)return; // costs focus
  const fx=-Math.sin(P.yaw),fz=-Math.cos(P.yaw),rx=Math.cos(P.yaw),rz=-Math.sin(P.yaw);
  let vx=0,vz=0;
  if(dirCode==='KeyW'){vx=fx;vz=fz;}
  else if(dirCode==='KeyS'){vx=-fx;vz=-fz;}
  else if(dirCode==='KeyA'){vx=-rx;vz=-rz;}
  else if(dirCode==='KeyD'){vx=rx;vz=rz;}
  else return;
  DODGE.active=true;DODGE.t=0;DODGE.vx=vx*9.5;DODGE.vz=vz*9.5;
  DODGE.iframeUntil=performance.now()+Math.round(DODGE.dur*1000)+60;
  P.focus=Math.max(0,P.focus-.18);
  sfxDodge();
}
function sfxDodge(){
  const c=getAC(),o=c.createOscillator(),g=c.createGain();
  o.type='sine';o.frequency.setValueAtTime(420,c.currentTime);
  o.frequency.exponentialRampToValueAtTime(180,c.currentTime+.20);
  g.gain.setValueAtTime(.18,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.22);
  o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.25);
}
function updateDodge(dt){
  if(!DODGE.active)return;
  DODGE.t+=dt;
  const ph=DODGE.t/DODGE.dur;
  if(ph>=1){DODGE.active=false;return;}
  // Move player along velocity, with smooth ease-out
  const ease=1-Math.pow(ph,2);
  const walls=G.levelData?G.levelData.walls:[];
  const R=PR;
  const nx=P.pos.x+DODGE.vx*ease*dt,nz=P.pos.z+DODGE.vz*ease*dt;
  let okX=true,okZ=true;
  for(const w of walls){
    if(w.broken)continue;
    if(nx+R>w.x0&&w.x1>nx-R&&P.pos.z+R>w.z0&&w.z1>P.pos.z-R)okX=false;
    if(P.pos.x+R>w.x0&&w.x1>P.pos.x-R&&nz+R>w.z0&&w.z1>nz-R)okZ=false;
  }
  if(okX)P.pos.x=nx;if(okZ)P.pos.z=nz;
  // Camera dip mid-roll
  PP.shakeY-=Math.sin(ph*Math.PI)*.08;
}
// ── STORY NARRATIVE — typewriter intro + epilogue cards ──────────────
// Three-act campaign:
//   Act I    (B01-B04): the family's foundation — break the spine.
//   Act II   (B05-B08): the family's command — burn the head.
//   Act III  (B09-B12): "The Apparatus" — the network above the family.
const STORY_BEATS=[
  // ── Act I prelude ───────────────────────────────────────────────
  {after:0, lines:[
    'Six years ago they took everything.',
    'Tonight, you take it all back.',
    'Twelve names. One night.',
    "The Vasari syndicate doesn't know it yet — they're already dead."
  ]},
  // ── Act I → Act II pivot (after building 4) ────────────────────
  {after:4, lines:[
    "Four down. The family's spine is broken.",
    "The Patriarch is in his bunker now.",
    "He thinks the back doors save him.",
    "Good. Easier to find them all in one place."
  ]},
  // ── Act II climax / Act III opening (after building 8) ─────────
  // Old "epilogue after 8" replaced with a new pivot: the Patriarch
  // is dead — but the customs ledger names someone higher.
  {after:8, lines:[
    "The Patriarch is dead.",
    "You found the ledger in his vault.",
    "The family was paying someone above them — every month, in cash.",
    "Tonight isn't over yet."
  ]},
  // ── Act III midpoint (after building 10 — Cathedral) ───────────
  {after:10, lines:[
    "The Cardinal kept books in three languages.",
    "All of them named the same man.",
    "Eldritch Asteria. The Director.",
    "He's boarding a helicopter at the Spire — four-forty-four."
  ]},
  // ── True ending (after building 12) ────────────────────────────
  {after:12, lines:[
    "He didn't even run.",
    "Just stood there, in the glass, watching the sunrise.",
    "Said you were always part of the apparatus too.",
    "Maybe. But you're the part that left.",
  ]}
];
function showStoryBeat(idx,cb){
  const beat=STORY_BEATS.find(b=>b.after===idx);
  if(!beat){if(cb)cb();return;}
  const layer=$e('story-card');
  if(!layer){if(cb)cb();return;}
  const linesEl=$e('story-lines');linesEl.innerHTML='';
  layer.classList.add('show');
  const webdriverFast=typeof navigator!=='undefined'&&navigator.webdriver;
  const typeDelay=webdriverFast?2:28;
  const lineDelay=webdriverFast?40:900;
  const lastLineDelay=webdriverFast?60:1500;
  const closeDelay=webdriverFast?120:1800;
  let lineIdx=0;
  function nextLine(){
    if(lineIdx>=beat.lines.length){
      setTimeout(()=>{
        layer.classList.remove('show');
        if(cb)cb();
      },closeDelay);
      return;
    }
    const line=beat.lines[lineIdx++];
    const lineEl=document.createElement('div');lineEl.className='story-line';
    linesEl.appendChild(lineEl);
    let charIdx=0;
    function tw(){
      lineEl.textContent=line.slice(0,charIdx);
      charIdx++;
      if(charIdx<=line.length+1)setTimeout(tw,typeDelay);
      else setTimeout(nextLine,(beat.lines.length>lineIdx?lineDelay:lastLineDelay));
    }
    tw();
  }
  nextLine();
}
