  const spawns=G.levelData.zoneSpawns||[[],[],[]];
  G.enemyMgr.spawnByZone(counts,spawns,Math.max(1,G.building||1),G.levelData.walls,G.levelData.spawnDoors);
  G.zoneEverPopulated=counts.map(n=>n>0);
