      if(Array.isArray(resumeState.weaponRes))P.weaponRes=resumeState.weaponRes.slice(0,WEAPONS.length);
      P.weaponIdx=normalizeWeaponIdx(resumeState.weaponIdx||START_WEAPON_IDX);
