  if(t.mesh){scene.remove(t.mesh);if(t.mesh.geometry)t.mesh.geometry.dispose();else if(t.mesh.traverse)t.mesh.traverse(o=>{if(o.geometry)o.geometry.dispose();});if(t.mesh.material&&t.mesh.material!==t.mat){if(Array.isArray(t.mesh.material))t.mesh.material.forEach(m=>m&&m.dispose&&m.dispose());else if(t.mesh.material.dispose)t.mesh.material.dispose();}}
